insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260831044258","statements":["-- MOVA Phase 1 — Vehicle photo storage bucket + Row-Level Security\\n\\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\\nvalues (\\n  ''vehicle-photos'',\\n  ''vehicle-photos'',\\n  true,\\n  10485760,\\n  array[''image/jpeg'', ''image/png'', ''image/webp'']\\n)\\non conflict (id) do update set\\n  public = excluded.public,\\n  file_size_limit = excluded.file_size_limit,\\n  allowed_mime_types = excluded.allowed_mime_types;\\n\\ndrop policy if exists \\"vehicle photos owner insert\\" on storage.objects;\\ncreate policy \\"vehicle photos owner insert\\" on storage.objects\\n  for insert to authenticated\\n  with check (\\n    bucket_id = ''vehicle-photos''\\n    and (storage.foldername(name))[1] = (select auth.uid()::text)\\n  );\\n\\ndrop policy if exists \\"vehicle photos owner update\\" on storage.objects;\\ncreate policy \\"vehicle photos owner update\\" on storage.objects\\n  for update to authenticated\\n  using (\\n    bucket_id = ''vehicle-photos''\\n    and (storage.foldername(name))[1] = (select auth.uid()::text)\\n  )\\n  with check (\\n    bucket_id = ''vehicle-photos''\\n    and (storage.foldername(name))[1] = (select auth.uid()::text)\\n  );\\n\\ndrop policy if exists \\"vehicle photos owner delete\\" on storage.objects;\\ncreate policy \\"vehicle photos owner delete\\" on storage.objects\\n  for delete to authenticated\\n  using (\\n    bucket_id = ''vehicle-photos''\\n    and (storage.foldername(name))[1] = (select auth.uid()::text)\\n  );\\n\\ndrop policy if exists \\"vehicle photos owner read\\" on storage.objects;\\ncreate policy \\"vehicle photos owner read\\" on storage.objects\\n  for select to authenticated\\n  using (\\n    bucket_id = ''vehicle-photos''\\n    and (storage.foldername(name))[1] = (select auth.uid()::text)\\n  );\\n\\ncreate unique index if not exists vehicle_photos_one_primary_per_vehicle\\n  on public.vehicle_photos (vehicle_id)\\n  where is_primary;\\n\\ncreate index if not exists vehicle_photos_vehicle_id_sort_idx\\n  on public.vehicle_photos (vehicle_id, sort_order);"],"name":"vehicle_photos_storage","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260905150325","statements":["-- MOVA Phase 2 — Reservation fee split + fee payment flow\\n--\\n-- Per-listing choice of who covers MOVA''s 8% service fee, a price snapshot on\\n-- the reservation, and the fields the fee-payment (Stripe Checkout) flow writes\\n-- back: payment status, the checkout session, and the seller contact / wire\\n-- details that are revealed to the buyer once the fee is paid.\\n\\ncreate type fee_responsibility as enum (''buyer_pays_full'', ''split'');\\ncreate type mova_fee_payment_status as enum (''pending'', ''paid'');\\n\\nalter table public.vehicles\\n  add column fee_responsibility fee_responsibility not null default ''buyer_pays_full'';\\n\\nalter table public.purchase_requests\\n  -- Snapshot of the vehicle price at reservation time. mova_fee_usd (the full\\n  -- 8% fee) already exists from the initial schema.\\n  add column vehicle_price_usd numeric(12,2),\\n  add column mova_fee_payment_status mova_fee_payment_status not null default ''pending'',\\n  add column mova_fee_stripe_session_id text,\\n  add column mova_fee_checkout_url text,\\n  add column seller_details_revealed_at timestamptz,\\n  -- Seller contact + name, snapshotted by the payments webhook when the fee is\\n  -- paid. Snapshotted (rather than joined) because RLS keeps a buyer from\\n  -- reading the seller''s users / seller_profiles rows directly.\\n  add column seller_name text,\\n  add column seller_email text,\\n  add column seller_phone text,\\n  add column seller_whatsapp text;\\n"],"name":"reservation_fee_split","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260907012904","statements":["-- MOVA Phase 3 — Shipper signup + rate marketplace + automated commission\\ndrop table if exists public.shipping_rates cascade;\\ndrop table if exists public.shipping_companies cascade;\\ndrop table if exists public.shipping_company_applications cascade;\\n\\ncreate type shipper_status as enum (''pending'', ''approved'', ''rejected'');\\ncreate type shipper_payment_status as enum (''good_standing'', ''past_due'', ''suspended'');\\ncreate type commission_charge_status as enum (''pending'', ''charged'', ''failed'');\\ncreate type shipment_request_status as enum (''pending'', ''completed'');\\n\\ncreate table public.shippers (\\n  id uuid primary key default uuid_generate_v4(),\\n  user_id uuid unique references public.users(id) on delete set null,\\n  company_name text not null,\\n  contact_name text not null,\\n  contact_email text not null,\\n  contact_phone text,\\n  fmc_oti_license_number text not null,\\n  service_countries text[] not null default ''{}'',\\n  status shipper_status not null default ''pending'',\\n  payment_status shipper_payment_status not null default ''good_standing'',\\n  terms_accepted_at timestamptz,\\n  stripe_customer_id text,\\n  stripe_payment_method_id text,\\n  reviewed_by uuid references public.users(id),\\n  rejection_reason text,\\n  reinstated_at timestamptz,\\n  created_at timestamptz not null default now()\\n);\\n\\ncreate table public.shipping_rates (\\n  id uuid primary key default uuid_generate_v4(),\\n  shipper_id uuid not null references public.shippers(id) on delete cascade,\\n  origin_region text not null,\\n  origin_port text,\\n  destination_country text not null,\\n  vehicle_size_type text,\\n  price numeric(12,2) not null check (price >= 0),\\n  currency text not null default ''USD'',\\n  active boolean not null default true,\\n  created_at timestamptz not null default now()\\n);\\n\\ncreate table public.shipment_requests (\\n  id uuid primary key default uuid_generate_v4(),\\n  shipper_id uuid not null references public.shippers(id) on delete cascade,\\n  shipping_rate_id uuid references public.shipping_rates(id) on delete set null,\\n  buyer_id uuid not null references public.users(id) on delete cascade,\\n  agreed_rate numeric(12,2) not null,\\n  currency text not null default ''USD'',\\n  commission_pct numeric(5,2) not null default 8,\\n  commission_owed numeric(12,2) not null default 0,\\n  commission_charge_status commission_charge_status not null default ''pending'',\\n  stripe_charge_id text,\\n  status shipment_request_status not null default ''pending'',\\n  shipper_details_revealed_at timestamptz,\\n  shipper_company_name text,\\n  shipper_contact_name text,\\n  shipper_contact_email text,\\n  shipper_contact_phone text,\\n  created_at timestamptz not null default now()\\n);\\n\\ncreate index shipping_rates_destination_idx\\n  on public.shipping_rates (destination_country) where active;\\ncreate index shipping_rates_shipper_idx on public.shipping_rates (shipper_id);\\ncreate index shipment_requests_shipper_idx on public.shipment_requests (shipper_id);\\ncreate index shipment_requests_buyer_idx on public.shipment_requests (buyer_id);\\n\\ncreate view public.shipper_rates_public\\nwith (security_invoker = false) as\\nselect\\n  r.id as rate_id,\\n  r.shipper_id,\\n  s.company_name,\\n  r.origin_region,\\n  r.origin_port,\\n  r.destination_country,\\n  r.vehicle_size_type,\\n  r.price,\\n  r.currency,\\n  s.payment_status\\nfrom public.shipping_rates r\\njoin public.shippers s on s.id = r.shipper_id\\nwhere r.active\\n  and s.status = ''approved''\\n  and s.payment_status <> ''suspended'';\\n\\ngrant select on public.shipper_rates_public to anon, authenticated;\\n\\nalter table public.shippers enable row level security;\\nalter table public.shipping_rates enable row level security;\\nalter table public.shipment_requests enable row level security;\\n\\ncreate policy \\"shippers signup insert\\" on public.shippers\\n  for insert with check (\\n    status = ''pending''\\n    and payment_status = ''good_standing''\\n    and (user_id is null or user_id = auth.uid())\\n  );\\ncreate policy \\"shippers owner or admin read\\" on public.shippers\\n  for select using (\\n    public.is_admin() or (user_id is not null and user_id = auth.uid())\\n  );\\ncreate policy \\"shippers admin update\\" on public.shippers\\n  for update using (public.is_admin()) with check (public.is_admin());\\n\\ncreate policy \\"shipping rates owner or admin read\\" on public.shipping_rates\\n  for select using (\\n    public.is_admin()\\n    or exists (\\n      select 1 from public.shippers s\\n      where s.id = shipper_id and s.user_id = auth.uid()\\n    )\\n  );\\ncreate policy \\"shipping rates admin write\\" on public.shipping_rates\\n  for all using (public.is_admin()) with check (public.is_admin());\\ncreate policy \\"shipping rates shipper write\\" on public.shipping_rates\\n  for all using (\\n    exists (\\n      select 1 from public.shippers s\\n      where s.id = shipper_id and s.user_id = auth.uid() and s.status = ''approved''\\n    )\\n  ) with check (\\n    exists (\\n      select 1 from public.shippers s\\n      where s.id = shipper_id and s.user_id = auth.uid() and s.status = ''approved''\\n    )\\n  );\\n\\ncreate policy \\"shipment requests read\\" on public.shipment_requests\\n  for select using (\\n    buyer_id = auth.uid()\\n    or public.is_admin()\\n    or exists (\\n      select 1 from public.shippers s\\n      where s.id = shipper_id and s.user_id = auth.uid()\\n    )\\n  );\\ncreate policy \\"shipment requests buyer insert\\" on public.shipment_requests\\n  for insert with check (\\n    buyer_id = auth.uid()\\n    and status = ''pending''\\n    and commission_charge_status = ''pending''\\n  );\\ncreate policy \\"shipment requests admin update\\" on public.shipment_requests\\n  for update using (public.is_admin()) with check (public.is_admin());"],"name":"shipper_marketplace","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260907013108","statements":["-- Column-level grants: hide the stripe_* token columns from anon/authenticated.\\nrevoke select on public.shippers from anon, authenticated;\\ngrant select (\\n  id, user_id, company_name, contact_name, contact_email, contact_phone,\\n  fmc_oti_license_number, service_countries, status, payment_status,\\n  terms_accepted_at, reviewed_by, rejection_reason, reinstated_at, created_at\\n) on public.shippers to anon, authenticated;\\n\\n-- Recreate the buyer-facing view as security_invoker so base-table RLS +\\n-- column grants both apply.\\ndrop view if exists public.shipper_rates_public;\\ncreate view public.shipper_rates_public\\nwith (security_invoker = true) as\\nselect\\n  r.id as rate_id,\\n  r.shipper_id,\\n  s.company_name,\\n  r.origin_region,\\n  r.origin_port,\\n  r.destination_country,\\n  r.vehicle_size_type,\\n  r.price,\\n  r.currency,\\n  s.payment_status\\nfrom public.shipping_rates r\\njoin public.shippers s on s.id = r.shipper_id\\nwhere r.active\\n  and s.status = ''approved''\\n  and s.payment_status <> ''suspended'';\\ngrant select on public.shipper_rates_public to anon, authenticated;\\n\\n-- Public read paths the view relies on.\\ncreate policy \\"shippers approved public read\\" on public.shippers\\n  for select using (status = ''approved'' and payment_status <> ''suspended'');\\ncreate policy \\"shipping rates public active read\\" on public.shipping_rates\\n  for select using (\\n    active and exists (\\n      select 1 from public.shippers s\\n      where s.id = shipper_id\\n        and s.status = ''approved''\\n        and s.payment_status <> ''suspended''\\n    )\\n  );"],"name":"shipper_marketplace_harden_rls","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260907013553","statements":["-- Non-sensitive derived flag so admin/shipper (the `authenticated` role, which\\n-- is not granted the stripe_* token columns) can tell whether a card is saved.\\n-- Set true by the shipper-commission webhook when it stores the PaymentMethod.\\nalter table public.shippers\\n  add column card_on_file boolean not null default false;\\n\\ngrant select (card_on_file) on public.shippers to anon, authenticated;"],"name":"shippers_card_on_file_flag","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260907013933","statements":["-- Tighten the public column surface: buyers (and the shipper_rates_public\\n-- view, which is security_invoker) only ever need these four. Contact details,\\n-- the FMC OTI license, card_on_file and the stripe_* tokens are read only via\\n-- the service role (admin pages + webhook). This keeps shipper contact info\\n-- gated behind an actual rate selection, matching the seller-contact pattern.\\nrevoke select on public.shippers from anon, authenticated;\\ngrant select (id, company_name, status, payment_status)\\n  on public.shippers to anon, authenticated;"],"name":"shippers_minimal_public_columns","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260907014619","statements":["-- Final column grant: anon/authenticated may read every shippers column EXCEPT\\n-- the two opaque Stripe token columns. Those stay readable only via the\\n-- service role (the commission webhook + completeShipment), so a crafted\\n-- PostgREST query for them is rejected. Admin pages need no service key just\\n-- to render the review queue.\\nrevoke select on public.shippers from anon, authenticated;\\ngrant select (\\n  id, user_id, company_name, contact_name, contact_email, contact_phone,\\n  fmc_oti_license_number, service_countries, status, payment_status,\\n  terms_accepted_at, card_on_file, reviewed_by, rejection_reason,\\n  reinstated_at, created_at\\n) on public.shippers to anon, authenticated;"],"name":"shippers_revoke_only_stripe_tokens","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260907224011","statements":["-- MOVA Phase 2 — Buyer <-> seller in-platform chat\\n\\ncreate table public.conversations (\\n  id uuid primary key default uuid_generate_v4(),\\n  vehicle_id uuid not null references public.vehicles(id) on delete cascade,\\n  buyer_id uuid not null references public.users(id) on delete cascade,\\n  seller_id uuid not null references public.users(id) on delete cascade,\\n  buyer_last_read_at timestamptz,\\n  seller_last_read_at timestamptz,\\n  created_at timestamptz not null default now(),\\n  unique (vehicle_id, buyer_id),\\n  constraint conversations_distinct_parties check (buyer_id <> seller_id)\\n);\\n\\ncreate index conversations_seller_idx\\n  on public.conversations (seller_id, created_at desc);\\ncreate index conversations_buyer_idx\\n  on public.conversations (buyer_id, created_at desc);\\ncreate index conversations_vehicle_idx on public.conversations (vehicle_id);\\n\\ncreate table public.messages (\\n  id uuid primary key default uuid_generate_v4(),\\n  conversation_id uuid not null references public.conversations(id) on delete cascade,\\n  sender_id uuid not null references public.users(id) on delete cascade,\\n  content text not null,\\n  blocked_attempt boolean not null default false,\\n  created_at timestamptz not null default now()\\n);\\n\\ncreate index messages_delivered_idx\\n  on public.messages (conversation_id, created_at)\\n  where blocked_attempt = false;\\ncreate index messages_blocked_idx\\n  on public.messages (created_at desc)\\n  where blocked_attempt = true;\\n\\nalter table public.conversations enable row level security;\\nalter table public.messages enable row level security;\\n\\ncreate policy \\"conversations participant read\\" on public.conversations\\n  for select using (\\n    buyer_id = auth.uid() or seller_id = auth.uid() or public.is_admin()\\n  );\\ncreate policy \\"conversations buyer insert\\" on public.conversations\\n  for insert with check (\\n    buyer_id = auth.uid()\\n    and buyer_id <> seller_id\\n    and exists (\\n      select 1 from public.vehicles v\\n      where v.id = conversations.vehicle_id\\n        and v.seller_id = conversations.seller_id\\n        and v.status = ''approved''\\n    )\\n  );\\n\\ncreate policy \\"messages participant read\\" on public.messages\\n  for select using (\\n    public.is_admin()\\n    or (\\n      blocked_attempt = false\\n      and exists (\\n        select 1 from public.conversations c\\n        where c.id = messages.conversation_id\\n          and (c.buyer_id = auth.uid() or c.seller_id = auth.uid())\\n      )\\n    )\\n  );"],"name":"buyer_seller_chat","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260908051729","statements":["create type review_type as enum (''buyer_to_seller'',''seller_to_buyer'',''buyer_to_shipper'');\\ncreate type review_status as enum (''pending'',''published'',''flagged'',''removed'');\\ncreate type review_report_status as enum (''open'',''reviewed'',''dismissed'');\\n\\ncreate table public.reviews (\\n  id uuid primary key default uuid_generate_v4(),\\n  review_type review_type not null,\\n  reviewer_id uuid not null references public.users(id) on delete cascade,\\n  reviewee_id uuid references public.users(id) on delete cascade,\\n  reviewee_shipper_id uuid references public.shippers(id) on delete cascade,\\n  purchase_request_id uuid references public.purchase_requests(id) on delete cascade,\\n  shipment_request_id uuid references public.shipment_requests(id) on delete cascade,\\n  rating smallint not null check (rating between 1 and 5),\\n  comment text,\\n  status review_status not null default ''pending'',\\n  moderated_by uuid references public.users(id),\\n  moderated_at timestamptz,\\n  moderation_note text,\\n  created_at timestamptz not null default now(),\\n  updated_at timestamptz not null default now(),\\n  constraint reviews_no_self check (reviewer_id is distinct from reviewee_id),\\n  constraint reviews_target_shape check (\\n    (review_type in (''buyer_to_seller'',''seller_to_buyer'') and reviewee_id is not null and reviewee_shipper_id is null)\\n    or (review_type = ''buyer_to_shipper'' and reviewee_id is null and reviewee_shipper_id is not null)\\n  ),\\n  constraint reviews_txn_shape check (\\n    (review_type in (''buyer_to_seller'',''seller_to_buyer'') and purchase_request_id is not null and shipment_request_id is null)\\n    or (review_type = ''buyer_to_shipper'' and shipment_request_id is not null and purchase_request_id is null)\\n  ),\\n  constraint reviews_comment_guard check (\\n    comment is null or (\\n      char_length(comment) <= 2000\\n      and comment !~ ''[0-9][-. ()0-9]{5,}[0-9]''\\n      and comment !~* ''@[a-z0-9._%+-]''\\n      and comment !~* ''(https?://|www\\\\.|[a-z0-9-]+\\\\.(com|net|org|io|co|app|dev|xyz|info|biz|ng|me|tv|uk|us|ru|link|site))''\\n    )\\n  )\\n);\\n\\ncreate unique index reviews_one_per_direction_per_txn on public.reviews (\\n  reviewer_id, review_type,\\n  coalesce(purchase_request_id, shipment_request_id),\\n  coalesce(reviewee_id, reviewee_shipper_id)\\n);\\ncreate index reviews_published_reviewee_idx on public.reviews (reviewee_id)\\n  where status = ''published'' and reviewee_id is not null;\\ncreate index reviews_published_shipper_idx on public.reviews (reviewee_shipper_id)\\n  where status = ''published'' and reviewee_shipper_id is not null;\\ncreate index reviews_moderation_idx on public.reviews (created_at)\\n  where status in (''pending'',''flagged'');\\ncreate index reviews_reviewer_idx on public.reviews (reviewer_id);\\n\\ncreate or replace function public.reviews_set_updated_at()\\nreturns trigger language plpgsql as $$\\nbegin\\n  new.updated_at := now();\\n  return new;\\nend $$;\\ncreate trigger reviews_touch_updated_at\\n  before update on public.reviews\\n  for each row execute function public.reviews_set_updated_at();\\n\\ncreate table public.review_reports (\\n  id uuid primary key default uuid_generate_v4(),\\n  review_id uuid not null references public.reviews(id) on delete cascade,\\n  reporter_id uuid not null references public.users(id) on delete cascade,\\n  reason text check (reason is null or char_length(reason) <= 500),\\n  status review_report_status not null default ''open'',\\n  resolved_by uuid references public.users(id),\\n  resolved_at timestamptz,\\n  created_at timestamptz not null default now(),\\n  unique (review_id, reporter_id)\\n);\\ncreate index review_reports_open_idx on public.review_reports (created_at) where status = ''open'';\\n\\ncreate or replace function public.flag_review_on_report()\\nreturns trigger language plpgsql security definer set search_path = public as $$\\nbegin\\n  update public.reviews set status = ''flagged''\\n   where id = new.review_id and status in (''pending'',''published'');\\n  return new;\\nend $$;\\ncreate trigger review_reports_flag_review\\n  after insert on public.review_reports\\n  for each row execute function public.flag_review_on_report();\\n\\nalter table public.reviews enable row level security;\\nalter table public.review_reports enable row level security;\\n\\ncreate policy \\"reviews public read published\\" on public.reviews\\n  for select using (status = ''published'');\\ncreate policy \\"reviews party read\\" on public.reviews\\n  for select using (\\n    reviewer_id = auth.uid()\\n    or reviewee_id = auth.uid()\\n    or public.is_admin()\\n    or exists (select 1 from public.shippers s where s.id = reviews.reviewee_shipper_id and s.user_id = auth.uid())\\n  );\\n\\ncreate policy \\"reviews insert when eligible\\" on public.reviews\\n  for insert to authenticated\\n  with check (\\n    reviewer_id = auth.uid()\\n    and status = ''pending''\\n    and rating between 1 and 5\\n    and reviewer_id is distinct from reviewee_id\\n    and (\\n      (\\n        review_type = ''buyer_to_seller''\\n        and reviewee_shipper_id is null and shipment_request_id is null\\n        and exists (\\n          select 1 from public.purchase_requests pr\\n          join public.vehicles v on v.id = pr.vehicle_id\\n          where pr.id = reviews.purchase_request_id\\n            and pr.buyer_id = auth.uid()\\n            and v.seller_id = reviews.reviewee_id\\n            and pr.mova_fee_payment_status = ''paid''\\n            and pr.seller_details_revealed_at is not null\\n        )\\n      )\\n      or (\\n        review_type = ''seller_to_buyer''\\n        and reviewee_shipper_id is null and shipment_request_id is null\\n        and exists (\\n          select 1 from public.purchase_requests pr\\n          join public.vehicles v on v.id = pr.vehicle_id\\n          where pr.id = reviews.purchase_request_id\\n            and v.seller_id = auth.uid()\\n            and pr.buyer_id = reviews.reviewee_id\\n            and pr.mova_fee_payment_status = ''paid''\\n            and pr.seller_details_revealed_at is not null\\n        )\\n      )\\n      or (\\n        review_type = ''buyer_to_shipper''\\n        and reviewee_id is null and purchase_request_id is null\\n        and exists (\\n          select 1 from public.shipment_requests sr\\n          where sr.id = reviews.shipment_request_id\\n            and sr.buyer_id = auth.uid()\\n            and sr.shipper_id = reviews.reviewee_shipper_id\\n            and sr.status = ''completed''\\n        )\\n      )\\n    )\\n  );\\n\\ncreate policy \\"reviews admin moderate\\" on public.reviews\\n  for update using (public.is_admin()) with check (public.is_admin());\\n\\ncreate policy \\"review reports insert\\" on public.review_reports\\n  for insert to authenticated\\n  with check (\\n    reporter_id = auth.uid()\\n    and exists (\\n      select 1 from public.reviews r\\n      where r.id = review_id and r.reviewer_id <> auth.uid()\\n        and (r.status = ''published'' or public.is_admin())\\n    )\\n  );\\ncreate policy \\"review reports read\\" on public.review_reports\\n  for select using (reporter_id = auth.uid() or public.is_admin());\\ncreate policy \\"review reports admin update\\" on public.review_reports\\n  for update using (public.is_admin()) with check (public.is_admin());\\n\\ncreate view public.seller_ratings with (security_invoker = true) as\\n  select reviewee_id as seller_id, round(avg(rating)::numeric, 2) as avg_rating, count(*)::int as review_count\\n  from public.reviews where review_type = ''buyer_to_seller'' and status = ''published'' group by reviewee_id;\\ncreate view public.buyer_ratings with (security_invoker = true) as\\n  select reviewee_id as buyer_id, round(avg(rating)::numeric, 2) as avg_rating, count(*)::int as review_count\\n  from public.reviews where review_type = ''seller_to_buyer'' and status = ''published'' group by reviewee_id;\\ncreate view public.shipper_ratings with (security_invoker = true) as\\n  select reviewee_shipper_id as shipper_id, round(avg(rating)::numeric, 2) as avg_rating, count(*)::int as review_count\\n  from public.reviews where review_type = ''buyer_to_shipper'' and status = ''published'' group by reviewee_shipper_id;\\n\\ngrant select on public.seller_ratings to anon, authenticated;\\ngrant select on public.buyer_ratings to anon, authenticated;\\ngrant select on public.shipper_ratings to anon, authenticated;"],"name":"reviews","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260908051754","statements":["-- Pin search_path on the trigger helper, and make both trigger functions\\n-- non-callable as RPC (they are trigger-only).\\nalter function public.reviews_set_updated_at() set search_path = '''';\\nrevoke execute on function public.reviews_set_updated_at() from public, anon, authenticated;\\nrevoke execute on function public.flag_review_on_report() from public, anon, authenticated;"],"name":"reviews_harden_functions","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260912205753","statements":["-- MOVA — Partial VIN display + admin VIN verification badge\\n--\\n-- (1) Partial VIN masking, enforced at the query/API level, not just the UI.\\n--     `vehicles.vin` keeps storing the full VIN as-is; what changes is who is\\n--     allowed to read the raw column. SELECT on that column is revoked from\\n--     `anon`/`authenticated`, so a raw REST call (e.g. GET\\n--     .../vehicles?select=vin with the anon key) is denied outright rather\\n--     than merely un-rendered by our UI. The only supported read path is the\\n--     `vehicle_vin_display` computed column below, backed by a SECURITY\\n--     DEFINER function that decides full vs. masked per row/caller:\\n--       - admins (public.is_admin())\\n--       - the listing''s own seller (seller_id = auth.uid())\\n--       - a buyer whose reservation has had MOVA''s fee paid and seller\\n--         details revealed — the same unlock point already used for seller\\n--         contact info (purchase_requests.mova_fee_payment_status = ''paid''\\n--         and seller_details_revealed_at is not null)\\n--     get the full VIN; everyone else gets the masked form (last 6 chars).\\n--\\n-- (2) vin_verification_status: set manually by admin after running NICB\\n--     VINCheck / NMVTIS lookups outside the app (no live API integration\\n--     yet). A ''flagged'' listing can never be approved — enforced by a CHECK\\n--     constraint (belt) and the admin approve action''s own filter (braces).\\n--     A trigger keeps this column admin-only: a seller''s own insert/update\\n--     on their listing (allowed broadly by the existing \\"vehicles seller\\n--     update own\\" RLS policy) can''t set or change it, even via a direct API\\n--     call that bypasses the app''s UI.\\n\\ncreate type vin_verification_status as enum (''unverified'', ''verified'', ''flagged'');\\n\\nalter table public.vehicles\\n  add column vin_verification_status vin_verification_status not null default ''unverified'';\\n\\nalter table public.vehicles\\n  add constraint vehicles_flagged_not_approved\\n  check (not (status = ''approved'' and vin_verification_status = ''flagged''));\\n\\n-- Keeps the last `keep` characters of `vin`, replacing the rest with one\\n-- bullet per masked character. Defensive about null/short values (dev/test\\n-- VINs) rather than erroring.\\ncreate or replace function public.mask_vin(vin text, keep int default 6)\\nreturns text\\nlanguage sql\\nimmutable\\nas $$\\n  select case\\n    when vin is null then null\\n    when length(vin) <= keep then vin\\n    else repeat(''•'', length(vin) - keep) || right(vin, keep)\\n  end;\\n$$;\\n\\n-- Computed column: `select id, vehicle_vin_display from vehicles`, or via\\n-- PostgREST `?select=vehicle_vin_display`. SECURITY DEFINER so it can read\\n-- the raw vin column on the caller''s behalf even though anon/authenticated\\n-- no longer have direct column privilege on it.\\ncreate or replace function public.vehicle_vin_display(v public.vehicles)\\nreturns text\\nlanguage sql\\nstable\\nsecurity definer\\nset search_path = public\\nas $$\\n  select case\\n    when public.is_admin() then v.vin\\n    when v.seller_id = auth.uid() then v.vin\\n    when exists (\\n      select 1 from public.purchase_requests pr\\n      where pr.vehicle_id = v.id\\n        and pr.buyer_id = auth.uid()\\n        and pr.mova_fee_payment_status = ''paid''\\n        and pr.seller_details_revealed_at is not null\\n    ) then v.vin\\n    else public.mask_vin(v.vin)\\n  end;\\n$$;\\n\\nrevoke select (vin) on public.vehicles from anon, authenticated;\\ngrant execute on function public.mask_vin(text, int) to anon, authenticated;\\ngrant execute on function public.vehicle_vin_display(public.vehicles) to anon, authenticated;\\n\\ncreate or replace function public.vehicles_guard_admin_only_fields()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if public.is_admin() then\\n    return new;\\n  end if;\\n  if tg_op = ''INSERT'' then\\n    new.vin_verification_status := ''unverified'';\\n  else\\n    new.vin_verification_status := old.vin_verification_status;\\n  end if;\\n  return new;\\nend;\\n$$;\\n\\ncreate trigger vehicles_guard_admin_only_fields\\n  before insert or update on public.vehicles\\n  for each row execute procedure public.vehicles_guard_admin_only_fields();\\n"],"name":"vin_verification","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260912205841","statements":["-- mask_vin had no pinned search_path (function_search_path_mutable lint).\\ncreate or replace function public.mask_vin(vin text, keep int default 6)\\nreturns text\\nlanguage sql\\nimmutable\\nset search_path = public\\nas $$\\n  select case\\n    when vin is null then null\\n    when length(vin) <= keep then vin\\n    else repeat(''•'', length(vin) - keep) || right(vin, keep)\\n  end;\\n$$;\\n\\n-- vehicles_guard_admin_only_fields is a trigger function only — it should\\n-- never be directly callable via RPC (it errors if invoked outside a trigger\\n-- context anyway, since its return type is `trigger`, but Postgres grants\\n-- EXECUTE to PUBLIC by default on new functions, which the advisor flags).\\nrevoke execute on function public.vehicles_guard_admin_only_fields() from public, anon, authenticated;\\n"],"name":"vin_verification_harden","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260912210152","statements":["create or replace function public.vehicles_guard_admin_only_fields()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if public.is_admin() then\\n    return new;\\n  end if;\\n\\n  if tg_op = ''INSERT'' then\\n    new.vin_verification_status := ''unverified'';\\n    new.verification_status := ''unverified'';\\n    new.title_history_check_status := ''not_run'';\\n    new.rejection_reason := null;\\n    new.status := ''draft'';\\n    return new;\\n  end if;\\n\\n  new.vin_verification_status := old.vin_verification_status;\\n  new.verification_status := old.verification_status;\\n  new.title_history_check_status := old.title_history_check_status;\\n  new.rejection_reason := old.rejection_reason;\\n\\n  if not (old.status = ''draft'' and new.status = ''pending_review'') then\\n    new.status := old.status;\\n  end if;\\n\\n  return new;\\nend;\\n$$;\\n"],"name":"vehicles_admin_decision_fields_guard","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260912211258","statements":["-- 1. users -------------------------------------------------------------------\\ncreate or replace function public.users_guard_admin_only_fields()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n  new.role := old.role;\\n  new.status := old.status;\\n  new.email_verified_at := old.email_verified_at;\\n  return new;\\nend;\\n$$;\\n\\ncreate trigger users_guard_admin_only_fields\\n  before update on public.users\\n  for each row execute procedure public.users_guard_admin_only_fields();\\n\\n-- 2a. seller_profiles ----------------------------------------------------\\ncreate or replace function public.seller_profiles_guard_admin_only_fields()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n\\n  if tg_op = ''INSERT'' then\\n    new.verification_status := ''unverified'';\\n    new.id_verified_at := null;\\n    if new.id_verification_status <> ''pending'' then\\n      new.id_verification_status := ''unverified'';\\n    end if;\\n    return new;\\n  end if;\\n\\n  new.verification_status := old.verification_status;\\n  new.id_verified_at := old.id_verified_at;\\n  if new.id_verification_status <> ''pending'' then\\n    new.id_verification_status := old.id_verification_status;\\n  end if;\\n  return new;\\nend;\\n$$;\\n\\ncreate trigger seller_profiles_guard_admin_only_fields\\n  before insert or update on public.seller_profiles\\n  for each row execute procedure public.seller_profiles_guard_admin_only_fields();\\n\\n-- 2b. buyer_profiles -------------------------------------------------------\\ncreate or replace function public.buyer_profiles_guard_admin_only_fields()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n\\n  if tg_op = ''INSERT'' then\\n    new.nin_verification_status := ''unverified'';\\n    new.bvn_verification_status := ''unverified'';\\n    new.verification_status := ''unverified'';\\n    return new;\\n  end if;\\n\\n  new.nin_verification_status := old.nin_verification_status;\\n  new.bvn_verification_status := old.bvn_verification_status;\\n  new.verification_status := old.verification_status;\\n  return new;\\nend;\\n$$;\\n\\ncreate trigger buyer_profiles_guard_admin_only_fields\\n  before insert or update on public.buyer_profiles\\n  for each row execute procedure public.buyer_profiles_guard_admin_only_fields();\\n\\n-- 3. notifications -----------------------------------------------------------\\ncreate or replace function public.notifications_guard_owner_fields()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n  new.user_id := old.user_id;\\n  new.type := old.type;\\n  new.payload := old.payload;\\n  new.created_at := old.created_at;\\n  return new;\\nend;\\n$$;\\n\\ncreate trigger notifications_guard_owner_fields\\n  before update on public.notifications\\n  for each row execute procedure public.notifications_guard_owner_fields();\\n\\n-- 4. vehicle_documents ------------------------------------------------------\\ncreate or replace function public.vehicle_documents_guard_visibility()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if not (public.is_admin() or auth.role() = ''service_role'') then\\n    new.visibility := ''admin_only'';\\n  end if;\\n  return new;\\nend;\\n$$;\\n\\ncreate trigger vehicle_documents_guard_visibility\\n  before insert on public.vehicle_documents\\n  for each row execute procedure public.vehicle_documents_guard_visibility();\\n\\nrevoke execute on function public.users_guard_admin_only_fields() from public, anon, authenticated;\\nrevoke execute on function public.seller_profiles_guard_admin_only_fields() from public, anon, authenticated;\\nrevoke execute on function public.buyer_profiles_guard_admin_only_fields() from public, anon, authenticated;\\nrevoke execute on function public.notifications_guard_owner_fields() from public, anon, authenticated;\\nrevoke execute on function public.vehicle_documents_guard_visibility() from public, anon, authenticated;\\n"],"name":"close_owner_write_rls_gaps","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260914020211","statements":["-- MOVA — Seller-negotiated reservation price\\n--\\n-- Sellers negotiate with buyers in chat and need to offer a lower final price\\n-- than the public listing without touching the listing itself. This adds a\\n-- per-reservation negotiated price to purchase_requests, buyer-gated so it\\n-- never takes effect silently.\\n--\\n-- public.vehicles.price_usd is never written by this migration or the code\\n-- that uses it — the public listing price stays fixed. A negotiated price\\n-- lives only on the one purchase_requests row it was proposed against; if the\\n-- buyer never accepts and the reservation is released/cancelled, the next\\n-- buyer''s reservation is a fresh row starting at negotiated_price_status =\\n-- ''none'', so the listing is effectively back at its original price with no\\n-- extra bookkeeping needed.\\n--\\n-- RLS SHAPE: same pattern as the vehicles/seller_profiles fixes in\\n-- 0009/0010. USING/WITH CHECK on an UPDATE policy can only gate *which row*\\n-- is touched, not *which columns* change, so:\\n--   - two new UPDATE policies grant row-level access (seller on their own\\n--     reservation''s vehicle; buyer on their own reservation) — deliberately\\n--     broad at the row level, with no column restriction in the policy itself\\n--   - a BEFORE UPDATE trigger is the actual column-level enforcement: it\\n--     reverts any column a non-admin/non-service-role actor isn''t allowed to\\n--     touch back to its old value, and validates the one transition each side\\n--     is allowed to make\\n--\\n-- Seller: may only set negotiated_price_status -> ''proposed'' together with a\\n-- negotiated_price_usd that is > 0 and strictly less than the reservation''s\\n-- price snapshot (vehicle_price_usd) — lower-only, enforced in the database,\\n-- not just the form — and only while the reservation is still open\\n-- (''submitted''/''under_review''/''verified'') and not already accepted. Every\\n-- other column reverts, including negotiated_price_status set to anything\\n-- other than ''proposed''.\\n--\\n-- Buyer: may only flip ''proposed'' -> ''accepted''. Cannot author\\n-- negotiated_price_usd themselves (reverted to old value) and cannot accept\\n-- out of ''none'' (nothing to accept). Every other column reverts.\\n--\\n-- Once accepted, negotiated_price_status = ''accepted'' is locked — the guard\\n-- only recognizes the seller''s ''proposed'' transition when the old status is\\n-- not already ''accepted'', so a further seller update reverts the negotiation\\n-- fields to their accepted values.\\n\\ncreate type negotiated_price_status as enum (''none'', ''proposed'', ''accepted'');\\n\\nalter table public.purchase_requests\\n  add column negotiated_price_usd numeric(12,2),\\n  add column negotiated_price_status negotiated_price_status not null default ''none'',\\n  add column negotiated_price_proposed_at timestamptz,\\n  add column negotiated_price_accepted_at timestamptz;\\n\\n-- A lower-only guard even for admin/service-role writes would be one edit\\n-- away from the constraint below being wrong for a legitimate correction, so\\n-- this stays a trigger-time check for non-privileged actors only (see the\\n-- function), not a table CHECK constraint.\\n\\ncreate or replace function public.purchase_requests_guard_negotiation()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\ndeclare\\n  v_is_seller boolean;\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n\\n  v_is_seller := exists (\\n    select 1 from public.vehicles v\\n    where v.id = old.vehicle_id and v.seller_id = auth.uid()\\n  );\\n\\n  if v_is_seller then\\n    if old.negotiated_price_status <> ''accepted''\\n       and new.negotiated_price_status = ''proposed''\\n       and new.negotiated_price_usd is not null\\n       and new.negotiated_price_usd > 0\\n       and new.negotiated_price_usd < coalesce(\\n             old.vehicle_price_usd,\\n             (select price_usd from public.vehicles where id = old.vehicle_id)\\n           )\\n       and old.status in (''submitted'', ''under_review'', ''verified'')\\n    then\\n      new.negotiated_price_proposed_at := now();\\n      new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    else\\n      -- Not a valid proposal (or reservation locked/closed) — revert the\\n      -- negotiation fields too, not just everything else below.\\n      new.negotiated_price_usd := old.negotiated_price_usd;\\n      new.negotiated_price_status := old.negotiated_price_status;\\n      new.negotiated_price_proposed_at := old.negotiated_price_proposed_at;\\n      new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    end if;\\n\\n    new.vehicle_id := old.vehicle_id;\\n    new.buyer_id := old.buyer_id;\\n    new.shipping_rate_id := old.shipping_rate_id;\\n    new.status := old.status;\\n    new.vehicle_price_usd := old.vehicle_price_usd;\\n    new.mova_fee_usd := old.mova_fee_usd;\\n    new.mova_fee_payment_status := old.mova_fee_payment_status;\\n    new.mova_fee_stripe_session_id := old.mova_fee_stripe_session_id;\\n    new.mova_fee_checkout_url := old.mova_fee_checkout_url;\\n    new.seller_details_revealed_at := old.seller_details_revealed_at;\\n    new.seller_name := old.seller_name;\\n    new.seller_email := old.seller_email;\\n    new.seller_phone := old.seller_phone;\\n    new.seller_whatsapp := old.seller_whatsapp;\\n    new.payment_method := old.payment_method;\\n    new.payment_reference := old.payment_reference;\\n    new.notes := old.notes;\\n    new.assigned_admin_id := old.assigned_admin_id;\\n    new.created_at := old.created_at;\\n    return new;\\n  end if;\\n\\n  if old.buyer_id = auth.uid() then\\n    if old.negotiated_price_status = ''proposed''\\n       and new.negotiated_price_status = ''accepted''\\n    then\\n      new.negotiated_price_accepted_at := now();\\n      new.negotiated_price_usd := old.negotiated_price_usd;\\n      new.negotiated_price_proposed_at := old.negotiated_price_proposed_at;\\n    else\\n      new.negotiated_price_status := old.negotiated_price_status;\\n      new.negotiated_price_usd := old.negotiated_price_usd;\\n      new.negotiated_price_proposed_at := old.negotiated_price_proposed_at;\\n      new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    end if;\\n\\n    new.vehicle_id := old.vehicle_id;\\n    new.buyer_id := old.buyer_id;\\n    new.shipping_rate_id := old.shipping_rate_id;\\n    new.status := old.status;\\n    new.vehicle_price_usd := old.vehicle_price_usd;\\n    new.mova_fee_usd := old.mova_fee_usd;\\n    new.mova_fee_payment_status := old.mova_fee_payment_status;\\n    new.mova_fee_stripe_session_id := old.mova_fee_stripe_session_id;\\n    new.mova_fee_checkout_url := old.mova_fee_checkout_url;\\n    new.seller_details_revealed_at := old.seller_details_revealed_at;\\n    new.seller_name := old.seller_name;\\n    new.seller_email := old.seller_email;\\n    new.seller_phone := old.seller_phone;\\n    new.seller_whatsapp := old.seller_whatsapp;\\n    new.payment_method := old.payment_method;\\n    new.payment_reference := old.payment_reference;\\n    new.notes := old.notes;\\n    new.assigned_admin_id := old.assigned_admin_id;\\n    new.created_at := old.created_at;\\n    return new;\\n  end if;\\n\\n  -- Neither this reservation''s seller nor its buyer. The RLS row policies\\n  -- below already scope UPDATE to those two (plus admin, handled above), so\\n  -- this shouldn''t be reachable — but revert everything rather than trust\\n  -- that alone.\\n  return old;\\nend;\\n$$;\\n\\ncreate trigger purchase_requests_guard_negotiation\\n  before update on public.purchase_requests\\n  for each row execute procedure public.purchase_requests_guard_negotiation();\\n\\nrevoke execute on function public.purchase_requests_guard_negotiation()\\n  from public, anon, authenticated;\\n\\n-- Row-level access. Column-level enforcement is entirely the trigger above —\\n-- these intentionally don''t try to restrict columns themselves.\\ncreate policy \\"purchase requests seller propose price\\" on public.purchase_requests\\n  for update\\n  using (\\n    exists (select 1 from public.vehicles v\\n      where v.id = purchase_requests.vehicle_id and v.seller_id = auth.uid())\\n  )\\n  with check (\\n    exists (select 1 from public.vehicles v\\n      where v.id = purchase_requests.vehicle_id and v.seller_id = auth.uid())\\n  );\\n\\ncreate policy \\"purchase requests buyer accept price\\" on public.purchase_requests\\n  for update\\n  using (buyer_id = auth.uid())\\n  with check (buyer_id = auth.uid());\\n"],"name":"negotiated_price","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260914020239","statements":["-- MOVA — Video upload for seller listings\\n--\\n-- Optional, at most one video per listing, alongside (not replacing) photos.\\n-- Same bucket/table/RLS shape as vehicle-photos (0002): public-read storage\\n-- bucket with server-side size/format limits, object key\\n-- \\"<seller uid>/<uuid>.<ext>\\" so ownership is the first path segment, and a\\n-- vehicle_videos row (mirroring vehicle_photos) pointing at the public URL.\\n--\\n-- Duration (max 90s) has no server-side equivalent to file_size_limit /\\n-- allowed_mime_types — Postgres/Storage can''t inspect an MP4 container''s\\n-- duration atom without transcoding infra. It''s enforced client-side before\\n-- upload starts; duration_seconds below is the client-reported value, stored\\n-- as an admin-visible signal during listing review, not as an access control.\\n\\n-- 1. Storage bucket -----------------------------------------------------------\\n-- 100 MB per video, mp4 only. Public-read so approved-listing videos render\\n-- without signed URLs, same as vehicle-photos.\\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\\nvalues (\\n  ''vehicle-videos'',\\n  ''vehicle-videos'',\\n  true,\\n  104857600,\\n  array[''video/mp4'']\\n)\\non conflict (id) do update set\\n  public = excluded.public,\\n  file_size_limit = excluded.file_size_limit,\\n  allowed_mime_types = excluded.allowed_mime_types;\\n\\n-- 2. storage.objects policies --------------------------------------------------\\n-- Object key convention: vehicle-videos/<seller uid>/<uuid>.mp4 — identical\\n-- ownership-via-path-segment pattern as vehicle-photos.\\ndrop policy if exists \\"vehicle videos owner insert\\" on storage.objects;\\ncreate policy \\"vehicle videos owner insert\\" on storage.objects\\n  for insert to authenticated\\n  with check (\\n    bucket_id = ''vehicle-videos''\\n    and (storage.foldername(name))[1] = (select auth.uid()::text)\\n  );\\n\\ndrop policy if exists \\"vehicle videos owner update\\" on storage.objects;\\ncreate policy \\"vehicle videos owner update\\" on storage.objects\\n  for update to authenticated\\n  using (\\n    bucket_id = ''vehicle-videos''\\n    and (storage.foldername(name))[1] = (select auth.uid()::text)\\n  )\\n  with check (\\n    bucket_id = ''vehicle-videos''\\n    and (storage.foldername(name))[1] = (select auth.uid()::text)\\n  );\\n\\ndrop policy if exists \\"vehicle videos owner delete\\" on storage.objects;\\ncreate policy \\"vehicle videos owner delete\\" on storage.objects\\n  for delete to authenticated\\n  using (\\n    bucket_id = ''vehicle-videos''\\n    and (storage.foldername(name))[1] = (select auth.uid()::text)\\n  );\\n\\ndrop policy if exists \\"vehicle videos owner read\\" on storage.objects;\\ncreate policy \\"vehicle videos owner read\\" on storage.objects\\n  for select to authenticated\\n  using (\\n    bucket_id = ''vehicle-videos''\\n    and (storage.foldername(name))[1] = (select auth.uid()::text)\\n  );\\n\\n-- 3. vehicle_videos table -----------------------------------------------------\\ncreate table public.vehicle_videos (\\n  id uuid primary key default uuid_generate_v4(),\\n  vehicle_id uuid not null references public.vehicles(id) on delete cascade,\\n  url text not null,\\n  duration_seconds numeric(6,2),\\n  created_at timestamptz not null default now()\\n);\\n\\n-- At most one video per vehicle — a second insert for the same vehicle_id\\n-- fails at the database, not just in the UI.\\ncreate unique index vehicle_videos_one_per_vehicle\\n  on public.vehicle_videos (vehicle_id);\\n\\nalter table public.vehicle_videos enable row level security;\\n\\ncreate policy \\"vehicle videos read\\" on public.vehicle_videos\\n  for select using (\\n    exists (select 1 from public.vehicles v\\n      where v.id = vehicle_id and (v.status = ''approved'' or v.seller_id = auth.uid() or public.is_admin()))\\n  );\\n\\ncreate policy \\"vehicle videos write by owner\\" on public.vehicle_videos\\n  for all using (\\n    exists (select 1 from public.vehicles v where v.id = vehicle_id and (v.seller_id = auth.uid() or public.is_admin()))\\n  ) with check (\\n    exists (select 1 from public.vehicles v where v.id = vehicle_id and (v.seller_id = auth.uid() or public.is_admin()))\\n  );\\n"],"name":"vehicle_video_storage","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260914084148","statements":["-- MOVA — Buyer Protection & Refund Policy acknowledgment\\n--\\n-- Two acceptance points:\\n--   1. Signup (buyer or seller) — a required checkbox in the signup form.\\n--   2. Fee payment (\\"Invoice 1\\") — a required checkbox on the buyer''s Pay\\n--      with Stripe step, confirming agreement to the specific fee/reservation\\n--      about to be paid.\\n--\\n-- SHAPE: a denormalized \\"current acceptance\\" snapshot on buyer_profiles /\\n-- seller_profiles (cheap to query for \\"who needs to be prompted to\\n-- re-accept\\"), plus an append-only audit log (public.policy_acceptances) that\\n-- is the actual record of reference for a dispute — every acceptance ever\\n-- made, including ones later superseded by a newer policy_version, with a\\n-- server-stamped timestamp/IP/user-agent that can never be edited via the\\n-- API once written.\\n--\\n-- PROFILE-ROW TIMING: buyer_profiles/seller_profiles rows aren''t created at\\n-- signup today (seller_profiles only appears once Identity verification\\n-- starts; buyer_profiles never had a creation path at all) — and this app\\n-- requires email confirmation before a session exists, so a client-side\\n-- upsert right after auth.signUp() would have no auth.uid() to write under.\\n-- Instead, the signup form passes policy_version through\\n-- auth.signUp()''s user metadata, and handle_new_user() (already\\n-- security definer, already reads `role` the same way) creates the profile\\n-- row and the signup-context audit row atomically, in the same trigger that\\n-- creates public.users — at the moment the checkbox was actually submitted,\\n-- not whenever email confirmation eventually happens.\\n\\ncreate type policy_acceptance_context as enum (''signup'', ''fee_payment'');\\n\\n-- 1. Append-only audit log -----------------------------------------------\\ncreate table public.policy_acceptances (\\n  id uuid primary key default uuid_generate_v4(),\\n  user_id uuid not null references public.users(id) on delete cascade,\\n  -- Derived server-side from public.users at insert time — see the guard\\n  -- trigger below. Never trusted from the caller.\\n  role user_role not null,\\n  context policy_acceptance_context not null,\\n  policy_version text not null,\\n  purchase_request_id uuid references public.purchase_requests(id) on delete cascade,\\n  -- Captured server-side (request headers), never client-supplied.\\n  ip_address text,\\n  user_agent text,\\n  accepted_at timestamptz not null default now(),\\n  constraint policy_acceptances_context_shape check (\\n    (context = ''fee_payment'' and purchase_request_id is not null) or\\n    (context = ''signup'' and purchase_request_id is null)\\n  )\\n);\\n\\ncreate index policy_acceptances_user_idx\\n  on public.policy_acceptances (user_id, accepted_at desc);\\ncreate index policy_acceptances_purchase_request_idx\\n  on public.policy_acceptances (purchase_request_id)\\n  where purchase_request_id is not null;\\n\\nalter table public.policy_acceptances enable row level security;\\n\\ncreate policy \\"policy acceptances self or admin read\\" on public.policy_acceptances\\n  for select using (user_id = auth.uid() or public.is_admin());\\n\\n-- Row-level access only. The trigger below is what actually protects\\n-- accepted_at/role from forgery; this just confirms the caller may log an\\n-- acceptance for themselves, and — for a fee_payment row — that the\\n-- reservation cited is actually theirs (an acceptance logged against\\n-- someone else''s reservation would be worthless as evidence).\\ncreate policy \\"policy acceptances self insert\\" on public.policy_acceptances\\n  for insert with check (\\n    user_id = auth.uid()\\n    and (\\n      purchase_request_id is null\\n      or exists (\\n        select 1 from public.purchase_requests pr\\n        where pr.id = purchase_request_id and pr.buyer_id = auth.uid()\\n      )\\n    )\\n  );\\n\\n-- Deliberately no UPDATE or DELETE policy for anyone, admin included. Once\\n-- written, a row is permanent via the API — a genuine correction would\\n-- require direct database access outside the app. For something that may be\\n-- referenced in a dispute, \\"nothing in the app can alter or delete an\\n-- acceptance record\\" is the point.\\n\\ncreate or replace function public.policy_acceptances_guard()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  -- accepted_at is always server time — never a caller-supplied timestamp,\\n  -- with no carve-out (including admin/service-role: there''s no legitimate\\n  -- reason to backdate one of these).\\n  new.accepted_at := now();\\n  -- role is always derived from the account being credited, never\\n  -- client-settable.\\n  select role into new.role from public.users where id = new.user_id;\\n  return new;\\nend;\\n$$;\\n\\ncreate trigger policy_acceptances_guard\\n  before insert on public.policy_acceptances\\n  for each row execute procedure public.policy_acceptances_guard();\\n\\nrevoke execute on function public.policy_acceptances_guard()\\n  from public, anon, authenticated;\\n\\n-- 2. Denormalized \\"current acceptance\\" snapshot ---------------------------\\nalter table public.buyer_profiles\\n  add column policy_accepted_at timestamptz,\\n  add column policy_version text;\\n\\nalter table public.seller_profiles\\n  add column policy_accepted_at timestamptz,\\n  add column policy_version text;\\n\\n-- 3. Extend the existing owner-write guard triggers (0010) to cover the two\\n-- new columns. Same idiom: a self-write is only accepted as a real\\n-- acceptance when policy_version actually changes to a non-null value —\\n-- accepted_at is then forced to server now(); a bare timestamp edit, a\\n-- no-op rewrite, or an attempt to null out a prior acceptance all revert to\\n-- the previous values instead.\\n\\ncreate or replace function public.seller_profiles_guard_admin_only_fields()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n\\n  if tg_op = ''INSERT'' then\\n    new.verification_status := ''unverified'';\\n    new.id_verified_at := null;\\n    if new.id_verification_status <> ''pending'' then\\n      new.id_verification_status := ''unverified'';\\n    end if;\\n    new.policy_accepted_at := case when new.policy_version is not null then now() else null end;\\n    return new;\\n  end if;\\n\\n  new.verification_status := old.verification_status;\\n  new.id_verified_at := old.id_verified_at;\\n  if new.id_verification_status <> ''pending'' then\\n    new.id_verification_status := old.id_verification_status;\\n  end if;\\n\\n  if new.policy_version is not null and new.policy_version is distinct from old.policy_version then\\n    new.policy_accepted_at := now();\\n  else\\n    new.policy_version := old.policy_version;\\n    new.policy_accepted_at := old.policy_accepted_at;\\n  end if;\\n\\n  return new;\\nend;\\n$$;\\n\\ncreate or replace function public.buyer_profiles_guard_admin_only_fields()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n\\n  if tg_op = ''INSERT'' then\\n    new.nin_verification_status := ''unverified'';\\n    new.bvn_verification_status := ''unverified'';\\n    new.verification_status := ''unverified'';\\n    new.policy_accepted_at := case when new.policy_version is not null then now() else null end;\\n    return new;\\n  end if;\\n\\n  new.nin_verification_status := old.nin_verification_status;\\n  new.bvn_verification_status := old.bvn_verification_status;\\n  new.verification_status := old.verification_status;\\n\\n  if new.policy_version is not null and new.policy_version is distinct from old.policy_version then\\n    new.policy_accepted_at := now();\\n  else\\n    new.policy_version := old.policy_version;\\n    new.policy_accepted_at := old.policy_accepted_at;\\n  end if;\\n\\n  return new;\\nend;\\n$$;\\n\\n-- 4. Seed the profile row + signup-context audit row at account creation --\\ncreate or replace function public.handle_new_user()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\ndeclare\\n  v_role user_role;\\n  v_policy_version text;\\nbegin\\n  v_role := coalesce((new.raw_user_meta_data->>''role'')::user_role, ''buyer'');\\n  v_policy_version := nullif(new.raw_user_meta_data->>''policy_version'', '''');\\n\\n  insert into public.users (id, email, role, status)\\n  values (new.id, new.email, v_role, ''active'');\\n\\n  if v_role = ''buyer'' then\\n    insert into public.buyer_profiles (user_id, policy_version)\\n    values (new.id, v_policy_version);\\n  elsif v_role = ''seller'' then\\n    insert into public.seller_profiles (user_id, policy_version)\\n    values (new.id, v_policy_version);\\n  end if;\\n\\n  -- Only log an acceptance if the signup form actually sent one — an admin-\\n  -- created account or any future signup path that doesn''t pass\\n  -- policy_version shouldn''t fabricate an acceptance that was never given.\\n  if v_policy_version is not null then\\n    insert into public.policy_acceptances (user_id, role, context, policy_version)\\n    values (new.id, v_role, ''signup'', v_policy_version);\\n  end if;\\n\\n  return new;\\nend;\\n$$;\\n"],"name":"buyer_protection_policy","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260915041321","statements":["-- MOVA — Bank-transfer fallback for the buyer''s MOVA service fee\\n--\\n-- Alongside the existing Stripe Checkout (\\"card\\") path, a buyer whose card\\n-- can''t complete an international payment can instead wire the fee and\\n-- upload proof of the transfer for an admin to manually confirm.\\n--\\n-- STATUS MODELING: this does NOT touch purchase_requests.status (the\\n-- reservation lifecycle — submitted/under_review/verified/…). It extends\\n-- mova_fee_payment_status instead, since that''s the column every existing\\n-- seller-detail-reveal check already gates on (''paid''). Bank transfer is\\n-- just another path to ''paid'':\\n--\\n--   pending -> pending_manual_verification -> paid\\n--                                          \\\\-> bank_transfer_rejected -> (buyer retries) -> pending_manual_verification\\n--\\n-- REFERENCE CODE: shown to the buyer and admin, derived deterministically\\n-- from purchase_requests.id (see lib/bank-transfer.ts). Deliberately not\\n-- stored anywhere — a derived value can''t drift out of sync with the row it\\n-- identifies.\\n--\\n-- COLUMN-LEVEL GUARD: same idiom as 0010/0011/0013 — RLS UPDATE policies\\n-- stay row-level only (\\"purchase requests buyer accept price\\" /\\n-- \\"purchase requests admin update\\", both already in place), and\\n-- purchase_requests_guard_negotiation (0011) is extended in place (not a\\n-- second trigger — see below for why) to be the actual column-level\\n-- enforcement:\\n--   - buyer: the ONLY transition permitted is\\n--     mova_fee_payment_status pending|bank_transfer_rejected -> pending_manual_verification,\\n--     together with payment_method = ''bank_transfer'' and a newly-set\\n--     bank_transfer_proof_path. ''paid'' is never a reachable target for a\\n--     buyer write, including a direct crafted PATCH. Admin-only review\\n--     fields (reviewed_by/reviewed_at/rejection_reason) can''t be set by the\\n--     buyer to anything — the happy path clears them to null (a fresh\\n--     upload starts a fresh review cycle), any other attempt reverts them.\\n--   - seller: no legitimate path at all; all bank-transfer columns revert.\\n--   - admin/service-role: unchanged, bypasses the guard entirely (already\\n--     true today) — app code (app/admin/reservations/actions.ts) does the\\n--     actual confirm/reject business logic, same trust level as every other\\n--     admin action in this codebase.\\n--\\n-- Extending the existing trigger function (rather than adding a second\\n-- BEFORE UPDATE trigger) avoids execution-order fights: multiple triggers on\\n-- the same table run in name order, each seeing the previous one''s NEW, and\\n-- 0011''s trigger already unconditionally reverts mova_fee_payment_status /\\n-- payment_method for buyer writes — a separate later-running trigger\\n-- couldn''t safely set them without knowing whether it runs before or after.\\n--\\n-- STORAGE: bank-transfer-proofs is a PRIVATE bucket (unlike vehicle-photos /\\n-- vehicle-videos) — this is a financial document, not listing media. Object\\n-- key convention: <buyer uid>/<purchase_request_id>/<uuid>.<ext>. Proof is\\n-- treated as evidence once uploaded: no UPDATE/DELETE policy for anyone\\n-- (same philosophy as policy_acceptances — nothing in the app can alter or\\n-- remove a submitted proof).\\n\\n-- 1. mova_fee_payment_status: new states ------------------------------------\\nalter type mova_fee_payment_status add value ''pending_manual_verification'';\\nalter type mova_fee_payment_status add value ''bank_transfer_rejected'';\\n\\n-- 2. purchase_requests: bank-transfer columns --------------------------------\\nalter table public.purchase_requests\\n  add column bank_transfer_proof_path text,\\n  add column bank_transfer_proof_uploaded_at timestamptz,\\n  add column bank_transfer_reviewed_by uuid references public.users(id),\\n  add column bank_transfer_reviewed_at timestamptz,\\n  add column bank_transfer_rejection_reason text;\\n\\n-- 3. Extend the column-level guard trigger -----------------------------------\\ncreate or replace function public.purchase_requests_guard_negotiation()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\ndeclare\\n  v_is_seller boolean;\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n\\n  v_is_seller := exists (\\n    select 1 from public.vehicles v\\n    where v.id = old.vehicle_id and v.seller_id = auth.uid()\\n  );\\n\\n  if v_is_seller then\\n    if old.negotiated_price_status <> ''accepted''\\n       and new.negotiated_price_status = ''proposed''\\n       and new.negotiated_price_usd is not null\\n       and new.negotiated_price_usd > 0\\n       and new.negotiated_price_usd < coalesce(\\n             old.vehicle_price_usd,\\n             (select price_usd from public.vehicles where id = old.vehicle_id)\\n           )\\n       and old.status in (''submitted'', ''under_review'', ''verified'')\\n    then\\n      new.negotiated_price_proposed_at := now();\\n      new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    else\\n      -- Not a valid proposal (or reservation locked/closed) — revert the\\n      -- negotiation fields too, not just everything else below.\\n      new.negotiated_price_usd := old.negotiated_price_usd;\\n      new.negotiated_price_status := old.negotiated_price_status;\\n      new.negotiated_price_proposed_at := old.negotiated_price_proposed_at;\\n      new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    end if;\\n\\n    new.vehicle_id := old.vehicle_id;\\n    new.buyer_id := old.buyer_id;\\n    new.shipping_rate_id := old.shipping_rate_id;\\n    new.status := old.status;\\n    new.vehicle_price_usd := old.vehicle_price_usd;\\n    new.mova_fee_usd := old.mova_fee_usd;\\n    new.mova_fee_payment_status := old.mova_fee_payment_status;\\n    new.mova_fee_stripe_session_id := old.mova_fee_stripe_session_id;\\n    new.mova_fee_checkout_url := old.mova_fee_checkout_url;\\n    new.seller_details_revealed_at := old.seller_details_revealed_at;\\n    new.seller_name := old.seller_name;\\n    new.seller_email := old.seller_email;\\n    new.seller_phone := old.seller_phone;\\n    new.seller_whatsapp := old.seller_whatsapp;\\n    new.payment_method := old.payment_method;\\n    new.payment_reference := old.payment_reference;\\n    -- Bank-transfer fields: sellers have no legitimate path to any of these.\\n    new.bank_transfer_proof_path := old.bank_transfer_proof_path;\\n    new.bank_transfer_proof_uploaded_at := old.bank_transfer_proof_uploaded_at;\\n    new.bank_transfer_reviewed_by := old.bank_transfer_reviewed_by;\\n    new.bank_transfer_reviewed_at := old.bank_transfer_reviewed_at;\\n    new.bank_transfer_rejection_reason := old.bank_transfer_rejection_reason;\\n    new.notes := old.notes;\\n    new.assigned_admin_id := old.assigned_admin_id;\\n    new.created_at := old.created_at;\\n    return new;\\n  end if;\\n\\n  if old.buyer_id = auth.uid() then\\n    if old.negotiated_price_status = ''proposed''\\n       and new.negotiated_price_status = ''accepted''\\n    then\\n      new.negotiated_price_accepted_at := now();\\n      new.negotiated_price_usd := old.negotiated_price_usd;\\n      new.negotiated_price_proposed_at := old.negotiated_price_proposed_at;\\n    else\\n      new.negotiated_price_status := old.negotiated_price_status;\\n      new.negotiated_price_usd := old.negotiated_price_usd;\\n      new.negotiated_price_proposed_at := old.negotiated_price_proposed_at;\\n      new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    end if;\\n\\n    -- Bank-transfer proof submission: the ONLY fee-payment-status transition\\n    -- a buyer can make is into ''pending_manual_verification'', paired with\\n    -- payment_method = ''bank_transfer'' and a freshly-set proof path. This is\\n    -- also the only path to ''paid'' this function will ever be asked to\\n    -- gate away from — ''paid'' itself never appears as an allowed new value\\n    -- below, from either starting state.\\n    if old.mova_fee_payment_status in (''pending'', ''bank_transfer_rejected'')\\n       and new.mova_fee_payment_status = ''pending_manual_verification''\\n       and new.payment_method = ''bank_transfer''\\n       and new.bank_transfer_proof_path is not null\\n       and new.bank_transfer_proof_path is distinct from old.bank_transfer_proof_path\\n    then\\n      new.bank_transfer_proof_uploaded_at := now();\\n      -- A fresh upload starts a fresh review cycle — clear any prior\\n      -- rejection rather than leaving stale admin fields on the row.\\n      new.bank_transfer_reviewed_by := null;\\n      new.bank_transfer_reviewed_at := null;\\n      new.bank_transfer_rejection_reason := null;\\n    else\\n      new.mova_fee_payment_status := old.mova_fee_payment_status;\\n      new.payment_method := old.payment_method;\\n      new.bank_transfer_proof_path := old.bank_transfer_proof_path;\\n      new.bank_transfer_proof_uploaded_at := old.bank_transfer_proof_uploaded_at;\\n      new.bank_transfer_reviewed_by := old.bank_transfer_reviewed_by;\\n      new.bank_transfer_reviewed_at := old.bank_transfer_reviewed_at;\\n      new.bank_transfer_rejection_reason := old.bank_transfer_rejection_reason;\\n    end if;\\n\\n    new.vehicle_id := old.vehicle_id;\\n    new.buyer_id := old.buyer_id;\\n    new.shipping_rate_id := old.shipping_rate_id;\\n    new.status := old.status;\\n    new.vehicle_price_usd := old.vehicle_price_usd;\\n    new.mova_fee_usd := old.mova_fee_usd;\\n    new.mova_fee_stripe_session_id := old.mova_fee_stripe_session_id;\\n    new.mova_fee_checkout_url := old.mova_fee_checkout_url;\\n    new.seller_details_revealed_at := old.seller_details_revealed_at;\\n    new.seller_name := old.seller_name;\\n    new.seller_email := old.seller_email;\\n    new.seller_phone := old.seller_phone;\\n    new.seller_whatsapp := old.seller_whatsapp;\\n    new.payment_reference := old.payment_reference;\\n    new.notes := old.notes;\\n    new.assigned_admin_id := old.assigned_admin_id;\\n    new.created_at := old.created_at;\\n    return new;\\n  end if;\\n\\n  -- Neither this reservation''s seller nor its buyer. The RLS row policies\\n  -- already scope UPDATE to those two (plus admin, handled above), so this\\n  -- shouldn''t be reachable — but revert everything rather than trust that\\n  -- alone.\\n  return old;\\nend;\\n$$;\\n\\nrevoke execute on function public.purchase_requests_guard_negotiation()\\n  from public, anon, authenticated;\\n\\n-- 4. Storage bucket -----------------------------------------------------------\\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\\nvalues (\\n  ''bank-transfer-proofs'',\\n  ''bank-transfer-proofs'',\\n  false,\\n  10485760,\\n  array[''image/jpeg'', ''image/png'', ''image/webp'', ''application/pdf'']\\n)\\non conflict (id) do update set\\n  public = excluded.public,\\n  file_size_limit = excluded.file_size_limit,\\n  allowed_mime_types = excluded.allowed_mime_types;\\n\\ndrop policy if exists \\"bank transfer proofs owner insert\\" on storage.objects;\\ncreate policy \\"bank transfer proofs owner insert\\" on storage.objects\\n  for insert to authenticated\\n  with check (\\n    bucket_id = ''bank-transfer-proofs''\\n    and (storage.foldername(name))[1] = (select auth.uid()::text)\\n    and exists (\\n      select 1 from public.purchase_requests pr\\n      where pr.id::text = (storage.foldername(name))[2]\\n        and pr.buyer_id = auth.uid()\\n    )\\n  );\\n\\ndrop policy if exists \\"bank transfer proofs owner read\\" on storage.objects;\\ncreate policy \\"bank transfer proofs owner read\\" on storage.objects\\n  for select to authenticated\\n  using (\\n    bucket_id = ''bank-transfer-proofs''\\n    and (\\n      (storage.foldername(name))[1] = (select auth.uid()::text)\\n      or public.is_admin()\\n    )\\n  );\\n"],"name":"bank_transfer_payment","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260915052729","statements":["create type dispute_category as enum (\\n  ''seller_unresponsive'',\\n  ''vehicle_misrepresented'',\\n  ''shipping_issue'',\\n  ''other''\\n);\\n\\ncreate type dispute_status as enum (\\n  ''open'',\\n  ''approved_pending_refund'',\\n  ''denied'',\\n  ''refund_completed''\\n);\\n\\ncreate table public.disputes (\\n  id uuid primary key default uuid_generate_v4(),\\n  purchase_request_id uuid not null references public.purchase_requests(id) on delete cascade,\\n  reporter_id uuid not null references public.users(id),\\n  category dispute_category not null,\\n  description text not null,\\n  evidence_paths text[] not null default ''{}'',\\n  status dispute_status not null default ''open'',\\n  decided_by uuid references public.users(id),\\n  decision_reason text,\\n  decision_amount_usd numeric(12,2),\\n  decided_at timestamptz,\\n  refund_completed_at timestamptz,\\n  created_at timestamptz not null default now()\\n);\\n\\ncreate index disputes_purchase_request_idx on public.disputes (purchase_request_id);\\ncreate index disputes_open_idx on public.disputes (created_at) where status = ''open'';\\n\\nalter table public.disputes enable row level security;\\n\\ncreate policy \\"disputes read\\" on public.disputes\\n  for select using (\\n    exists (\\n      select 1 from public.purchase_requests pr\\n      where pr.id = purchase_request_id\\n      and (pr.buyer_id = auth.uid()\\n           or exists (select 1 from public.vehicles v where v.id = pr.vehicle_id and v.seller_id = auth.uid())\\n           or public.is_admin())\\n    )\\n  );\\n\\ncreate policy \\"disputes reporter insert\\" on public.disputes\\n  for insert with check (\\n    reporter_id = auth.uid()\\n    and status = ''open''\\n    and decided_by is null\\n    and decision_reason is null\\n    and decision_amount_usd is null\\n    and decided_at is null\\n    and refund_completed_at is null\\n    and exists (\\n      select 1 from public.purchase_requests pr\\n      where pr.id = purchase_request_id\\n      and (pr.buyer_id = auth.uid()\\n           or exists (select 1 from public.vehicles v where v.id = pr.vehicle_id and v.seller_id = auth.uid()))\\n    )\\n  );\\n\\ncreate policy \\"disputes admin update\\" on public.disputes\\n  for update using (public.is_admin()) with check (public.is_admin());\\n\\n-- Storage bucket -------------------------------------------------------------\\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\\nvalues (\\n  ''dispute-evidence'',\\n  ''dispute-evidence'',\\n  false,\\n  10485760,\\n  array[''image/jpeg'', ''image/png'', ''image/webp'', ''application/pdf'']\\n)\\non conflict (id) do update set\\n  public = excluded.public,\\n  file_size_limit = excluded.file_size_limit,\\n  allowed_mime_types = excluded.allowed_mime_types;\\n\\ndrop policy if exists \\"dispute evidence owner insert\\" on storage.objects;\\ncreate policy \\"dispute evidence owner insert\\" on storage.objects\\n  for insert to authenticated\\n  with check (\\n    bucket_id = ''dispute-evidence''\\n    and (storage.foldername(name))[1] = (select auth.uid()::text)\\n  );\\n\\ndrop policy if exists \\"dispute evidence owner or admin read\\" on storage.objects;\\ncreate policy \\"dispute evidence owner or admin read\\" on storage.objects\\n  for select to authenticated\\n  using (\\n    bucket_id = ''dispute-evidence''\\n    and (\\n      (storage.foldername(name))[1] = (select auth.uid()::text)\\n      or public.is_admin()\\n    )\\n  );\\n"],"name":"disputes","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260916043856","statements":["-- MOVA — Shipper dashboard (/shipper/dashboard, /shipper/profile)\\n--\\n-- Adds what a shipper needs to manage their own assigned shipments and\\n-- profile day-to-day, without touching anything billing- or\\n-- approval-related (those stay admin/webhook-owned).\\n--\\n-- 1. LINKAGE GAP: shipment_requests had no link to the vehicle sale it''s\\n--    for — only (shipper_id, buyer_id). A buyer who bought two vehicles and\\n--    picked the same shipper for both would collide into one row (the old\\n--    app-level \\"one shipment request per buyer + shipper\\" dedupe in\\n--    selectShippingRate never accounted for the vehicle). Adds\\n--    purchase_request_id and a real uniqueness constraint on\\n--    (purchase_request_id, shipper_id).\\n--\\n-- 2. STATUS SPLIT: shipment_requests.status (''pending''/''completed'') is\\n--    billing-owned — the admin \\"mark shipment completed\\" action flips it to\\n--    trigger the Stripe commission charge, and the reviews system (0006)\\n--    gates buyer->shipper review eligibility on status = ''completed''.\\n--    Shippers must NOT be able to set this themselves. A new\\n--    shipping_status column (awaiting_pickup -> picked_up -> in_transit ->\\n--    delivered) is the shipper-owned logistics status; it never touches\\n--    billing or review eligibility. Free movement between the four values\\n--    is allowed (no forward-only enforcement) — this is a low-stakes\\n--    logistics label with no financial/security consequence, and a\\n--    non-technical shipper mis-tapping the wrong one should be able to\\n--    correct it without contacting support.\\n--\\n-- 3. BUYER CONTACT REVEAL: mirrors the existing precedent exactly — the\\n--    shipper''s own contact is already snapshotted onto shipment_requests and\\n--    revealed to the buyer unconditionally at row-insert time\\n--    (shipper_details_revealed_at in selectShippingRate), not gated on the\\n--    MOVA fee being paid. The new buyer_* columns do the same in reverse.\\n--\\n-- 4. RLS SHAPE for the two owner-write surfaces this adds (shippers editing\\n--    their own profile; shippers updating shipping_status) follows the\\n--    0009/0010/0011 pattern: USING/WITH CHECK only gates *which row*, not\\n--    *which columns* change, so each gets a broad owner-row UPDATE policy\\n--    plus a BEFORE UPDATE trigger that reverts every other column to its old\\n--    value for any non-admin/non-service-role actor.\\n--\\n-- 5. shipment_proof_photos / shipment_updates are new, permanent-record\\n--    tables (no update/delete policy for anyone) — same shape as\\n--    dispute-evidence (0015): shipper (owner) inserts, shipper + buyer +\\n--    admin read.\\n\\n-- 1. Link shipment_requests to its purchase_request ---------------------------\\nalter table public.shipment_requests\\n  add column purchase_request_id uuid references public.purchase_requests(id);\\n\\n-- Backfill: this project''s one existing row ties to its buyer''s one paid\\n-- purchase_request.\\nupdate public.shipment_requests sr\\nset purchase_request_id = (\\n  select pr.id from public.purchase_requests pr\\n  where pr.buyer_id = sr.buyer_id\\n  order by (pr.mova_fee_payment_status = ''paid'') desc, pr.created_at asc\\n  limit 1\\n)\\nwhere sr.purchase_request_id is null;\\n\\nalter table public.shipment_requests\\n  alter column purchase_request_id set not null;\\n\\ncreate unique index shipment_requests_purchase_request_shipper_idx\\n  on public.shipment_requests (purchase_request_id, shipper_id);\\n\\n-- 2. Shipper-owned logistics status, separate from billing status -------------\\ncreate type shipment_shipping_status as enum (\\n  ''awaiting_pickup'', ''picked_up'', ''in_transit'', ''delivered''\\n);\\n\\nalter table public.shipment_requests\\n  add column shipping_status shipment_shipping_status not null default ''awaiting_pickup'',\\n  add column shipping_status_updated_at timestamptz;\\n\\n-- 3. Buyer contact snapshot, revealed to the shipper (mirrors shipper_*) ------\\nalter table public.shipment_requests\\n  add column buyer_details_revealed_at timestamptz,\\n  add column buyer_name text,\\n  add column buyer_email text,\\n  add column buyer_phone text,\\n  add column buyer_whatsapp text;\\n\\nupdate public.shipment_requests sr\\nset\\n  buyer_details_revealed_at = coalesce(sr.buyer_details_revealed_at, sr.created_at),\\n  buyer_name = bp.full_name,\\n  buyer_email = u.email,\\n  buyer_phone = u.phone,\\n  buyer_whatsapp = u.whatsapp_number\\nfrom public.users u\\nleft join public.buyer_profiles bp on bp.user_id = u.id\\nwhere u.id = sr.buyer_id\\n  and sr.buyer_details_revealed_at is null;\\n\\n-- 4a. shipment_requests: shipper may update shipping_status only -------------\\ncreate or replace function public.shipment_requests_guard_shipping_status()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n\\n  if not exists (\\n    select 1 from public.shippers s\\n    where s.id = old.shipper_id and s.user_id = auth.uid()\\n  ) then\\n    -- Not the owning shipper (RLS below shouldn''t allow reaching here, but\\n    -- don''t trust that alone) — revert everything.\\n    return old;\\n  end if;\\n\\n  new.shipping_status_updated_at :=\\n    case when new.shipping_status is distinct from old.shipping_status\\n         then now()\\n         else old.shipping_status_updated_at\\n    end;\\n\\n  new.shipper_id := old.shipper_id;\\n  new.shipping_rate_id := old.shipping_rate_id;\\n  new.buyer_id := old.buyer_id;\\n  new.purchase_request_id := old.purchase_request_id;\\n  new.agreed_rate := old.agreed_rate;\\n  new.currency := old.currency;\\n  new.commission_pct := old.commission_pct;\\n  new.commission_owed := old.commission_owed;\\n  new.commission_charge_status := old.commission_charge_status;\\n  new.stripe_charge_id := old.stripe_charge_id;\\n  new.status := old.status;\\n  new.shipper_details_revealed_at := old.shipper_details_revealed_at;\\n  new.shipper_company_name := old.shipper_company_name;\\n  new.shipper_contact_name := old.shipper_contact_name;\\n  new.shipper_contact_email := old.shipper_contact_email;\\n  new.shipper_contact_phone := old.shipper_contact_phone;\\n  new.buyer_details_revealed_at := old.buyer_details_revealed_at;\\n  new.buyer_name := old.buyer_name;\\n  new.buyer_email := old.buyer_email;\\n  new.buyer_phone := old.buyer_phone;\\n  new.buyer_whatsapp := old.buyer_whatsapp;\\n  new.created_at := old.created_at;\\n  return new;\\nend;\\n$$;\\n\\ncreate trigger shipment_requests_guard_shipping_status\\n  before update on public.shipment_requests\\n  for each row execute procedure public.shipment_requests_guard_shipping_status();\\n\\nrevoke execute on function public.shipment_requests_guard_shipping_status()\\n  from public, anon, authenticated;\\n\\ncreate policy \\"shipment requests shipper update shipping status\\" on public.shipment_requests\\n  for update\\n  using (\\n    exists (select 1 from public.shippers s where s.id = shipper_id and s.user_id = auth.uid())\\n  )\\n  with check (\\n    exists (select 1 from public.shippers s where s.id = shipper_id and s.user_id = auth.uid())\\n  );\\n\\n-- 4b. shippers: owner may edit company_name / service_countries / description\\nalter table public.shippers\\n  add column description text;\\n\\nrevoke select on public.shippers from anon, authenticated;\\ngrant select (\\n  id, user_id, company_name, contact_name, contact_email, contact_phone,\\n  fmc_oti_license_number, service_countries, status, payment_status,\\n  terms_accepted_at, card_on_file, reviewed_by, rejection_reason,\\n  reinstated_at, description, created_at\\n) on public.shippers to anon, authenticated;\\n\\ncreate or replace function public.shippers_guard_owner_editable_fields()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n\\n  if not (old.user_id is not null and old.user_id = auth.uid()) then\\n    return old;\\n  end if;\\n\\n  -- Editable by the owning shipper: company_name, service_countries,\\n  -- description. Everything else reverts.\\n  new.id := old.id;\\n  new.user_id := old.user_id;\\n  new.contact_name := old.contact_name;\\n  new.contact_email := old.contact_email;\\n  new.contact_phone := old.contact_phone;\\n  new.fmc_oti_license_number := old.fmc_oti_license_number;\\n  new.status := old.status;\\n  new.payment_status := old.payment_status;\\n  new.terms_accepted_at := old.terms_accepted_at;\\n  new.stripe_customer_id := old.stripe_customer_id;\\n  new.stripe_payment_method_id := old.stripe_payment_method_id;\\n  new.card_on_file := old.card_on_file;\\n  new.reviewed_by := old.reviewed_by;\\n  new.rejection_reason := old.rejection_reason;\\n  new.reinstated_at := old.reinstated_at;\\n  new.created_at := old.created_at;\\n  return new;\\nend;\\n$$;\\n\\ncreate trigger shippers_guard_owner_editable_fields\\n  before update on public.shippers\\n  for each row execute procedure public.shippers_guard_owner_editable_fields();\\n\\nrevoke execute on function public.shippers_guard_owner_editable_fields()\\n  from public, anon, authenticated;\\n\\ncreate policy \\"shippers owner update\\" on public.shippers\\n  for update\\n  using (user_id = auth.uid())\\n  with check (user_id = auth.uid());\\n\\n-- 5. Proof-of-pickup / proof-of-delivery photos --------------------------------\\ncreate type shipment_proof_kind as enum (''pickup'', ''delivery'');\\n\\ncreate table public.shipment_proof_photos (\\n  id uuid primary key default uuid_generate_v4(),\\n  shipment_request_id uuid not null references public.shipment_requests(id) on delete cascade,\\n  kind shipment_proof_kind not null,\\n  storage_path text not null,\\n  uploaded_by uuid not null references public.users(id),\\n  created_at timestamptz not null default now()\\n);\\n\\ncreate index shipment_proof_photos_shipment_idx\\n  on public.shipment_proof_photos (shipment_request_id);\\n\\nalter table public.shipment_proof_photos enable row level security;\\n\\ncreate policy \\"shipment proof photos read\\" on public.shipment_proof_photos\\n  for select using (\\n    public.is_admin()\\n    or exists (\\n      select 1 from public.shipment_requests sr\\n      where sr.id = shipment_request_id\\n        and (\\n          sr.buyer_id = auth.uid()\\n          or exists (select 1 from public.shippers s where s.id = sr.shipper_id and s.user_id = auth.uid())\\n        )\\n    )\\n  );\\n\\ncreate policy \\"shipment proof photos shipper insert\\" on public.shipment_proof_photos\\n  for insert with check (\\n    uploaded_by = auth.uid()\\n    and exists (\\n      select 1 from public.shipment_requests sr\\n      join public.shippers s on s.id = sr.shipper_id\\n      where sr.id = shipment_request_id and s.user_id = auth.uid()\\n    )\\n  );\\n\\n-- Storage bucket. Object key convention:\\n-- shipment-proof-photos/<shipper uid>/<uuid>.<ext> — folder-scoped insert\\n-- exactly like vehicle-photos/dispute-evidence. Read also needs to reach the\\n-- buyer (whose uid won''t match the shipper''s folder), so that branch joins\\n-- through shipment_proof_photos.storage_path -> shipment_requests.buyer_id.\\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\\nvalues (\\n  ''shipment-proof-photos'',\\n  ''shipment-proof-photos'',\\n  false,\\n  10485760,\\n  array[''image/jpeg'', ''image/png'', ''image/webp'']\\n)\\non conflict (id) do update set\\n  public = excluded.public,\\n  file_size_limit = excluded.file_size_limit,\\n  allowed_mime_types = excluded.allowed_mime_types;\\n\\ndrop policy if exists \\"shipment proof photos owner insert\\" on storage.objects;\\ncreate policy \\"shipment proof photos owner insert\\" on storage.objects\\n  for insert to authenticated\\n  with check (\\n    bucket_id = ''shipment-proof-photos''\\n    and (storage.foldername(name))[1] = (select auth.uid()::text)\\n  );\\n\\ndrop policy if exists \\"shipment proof photos read\\" on storage.objects;\\ncreate policy \\"shipment proof photos read\\" on storage.objects\\n  for select to authenticated\\n  using (\\n    bucket_id = ''shipment-proof-photos''\\n    and (\\n      (storage.foldername(name))[1] = (select auth.uid()::text)\\n      or public.is_admin()\\n      or exists (\\n        select 1 from public.shipment_proof_photos spp\\n        join public.shipment_requests sr on sr.id = spp.shipment_request_id\\n        where spp.storage_path = name and sr.buyer_id = auth.uid()\\n      )\\n    )\\n  );\\n\\n-- No update/delete policy for anyone — proof is permanent once submitted,\\n-- same as dispute-evidence and bank-transfer-proofs.\\n\\n-- 6. Buyer-visible shipment notes ---------------------------------------------\\ncreate table public.shipment_updates (\\n  id uuid primary key default uuid_generate_v4(),\\n  shipment_request_id uuid not null references public.shipment_requests(id) on delete cascade,\\n  author_id uuid not null references public.users(id),\\n  note text not null,\\n  created_at timestamptz not null default now()\\n);\\n\\ncreate index shipment_updates_shipment_idx\\n  on public.shipment_updates (shipment_request_id, created_at);\\n\\nalter table public.shipment_updates enable row level security;\\n\\ncreate policy \\"shipment updates read\\" on public.shipment_updates\\n  for select using (\\n    public.is_admin()\\n    or exists (\\n      select 1 from public.shipment_requests sr\\n      where sr.id = shipment_request_id\\n        and (\\n          sr.buyer_id = auth.uid()\\n          or exists (select 1 from public.shippers s where s.id = sr.shipper_id and s.user_id = auth.uid())\\n        )\\n    )\\n  );\\n\\ncreate policy \\"shipment updates shipper insert\\" on public.shipment_updates\\n  for insert with check (\\n    author_id = auth.uid()\\n    and exists (\\n      select 1 from public.shipment_requests sr\\n      join public.shippers s on s.id = sr.shipper_id\\n      where sr.id = shipment_request_id and s.user_id = auth.uid()\\n    )\\n  );\\n\\n-- No update/delete policy for anyone — same permanent-record shape.\\n"],"name":"shipper_dashboard","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260916045035","statements":["-- MOVA — snapshot vehicle info onto shipment_requests\\n--\\n-- The shipper dashboard needs the vehicle''s make/model/year and pickup\\n-- location per shipment. Joining through purchase_request_id -> vehicles\\n-- would need a new shipper-read policy on purchase_requests — but that row\\n-- carries the seller''s revealed contact info, payment_method/reference,\\n-- negotiated price, and admin notes, none of which are column-restricted\\n-- (unlike shippers'' Stripe token columns), so a row-level grant there would\\n-- hand a shipper far more than a vehicle description. Snapshotting instead\\n-- follows the same pattern already used for shipper_*/buyer_* contact: no\\n-- new cross-table read policy needed at all.\\n\\nalter table public.shipment_requests\\n  add column vehicle_year integer,\\n  add column vehicle_make text,\\n  add column vehicle_model text,\\n  add column vehicle_trim text,\\n  add column pickup_city text,\\n  add column pickup_state text;\\n\\n-- Backfill this project''s one existing row.\\nupdate public.shipment_requests sr\\nset\\n  vehicle_year = v.year,\\n  vehicle_make = v.make,\\n  vehicle_model = v.model,\\n  vehicle_trim = v.trim,\\n  pickup_city = v.location_city,\\n  pickup_state = v.location_state\\nfrom public.purchase_requests pr\\njoin public.vehicles v on v.id = pr.vehicle_id\\nwhere pr.id = sr.purchase_request_id\\n  and sr.vehicle_make is null;\\n"],"name":"shipment_requests_vehicle_snapshot","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260916132503","statements":["-- 1. New structured dimensions -----------------------------------------------\\ncreate type vehicle_size_type as enum (''sedan'', ''suv_truck'');\\n-- shipping_method already exists — created in 0001_init.sql for the\\n-- original Phase-0 scaffold (''roro'', ''container'', exactly what''s needed\\n-- here) and never dropped when 0004 removed that scaffold''s tables.\\n\\n-- 2. vehicles: seller-set size class, same as transmission/condition today —\\n-- no RLS/trigger change needed, the existing seller-write policy already\\n-- covers any plain column on the seller''s own row.\\nalter table public.vehicles\\n  add column vehicle_size_type vehicle_size_type;\\n\\n-- Backfill the one live listing (2003 Honda Accord — a sedan) before making\\n-- the column required for everything going forward.\\nupdate public.vehicles set vehicle_size_type = ''sedan'' where vehicle_size_type is null;\\n\\nalter table public.vehicles\\n  alter column vehicle_size_type set not null;\\n\\n-- 3. shipping_rates: convert vehicle_size_type to the real enum, add\\n-- shipping_method, both required. The one live rate row (vehicle_size_type\\n-- null) doesn''t fit the structured model — deactivated rather than guessed\\n-- at; the shipper re-adds it properly through the new rate-management UI.\\nupdate public.shipping_rates\\nset active = false, vehicle_size_type = ''sedan''\\nwhere vehicle_size_type is null;\\n\\n-- shipper_rates_public selects vehicle_size_type directly, which blocks an\\n-- ALTER COLUMN TYPE while it exists — drop and recreate around it.\\ndrop view public.shipper_rates_public;\\n\\nalter table public.shipping_rates\\n  alter column vehicle_size_type type vehicle_size_type\\n  using vehicle_size_type::vehicle_size_type;\\n\\nalter table public.shipping_rates\\n  alter column vehicle_size_type set not null,\\n  add column shipping_method shipping_method not null default ''roro'';\\n\\nalter table public.shipping_rates\\n  alter column shipping_method drop default;\\n\\n-- One row per (shipper, destination, size, method). origin_region is\\n-- deliberately NOT part of this key — it''s shipper-entered descriptive text,\\n-- never used in any buyer-side matching query (destination_country is the\\n-- only geography filter applied anywhere in app/), so two rows differing\\n-- only in origin_region would be indistinguishable to a buyer and just create\\n-- ambiguity about which price applies.\\ncreate unique index shipping_rates_shipper_destination_size_method_idx\\n  on public.shipping_rates (shipper_id, destination_country, vehicle_size_type, shipping_method);\\n\\n-- shipper_rates_public (0004) needs the new column surfaced to buyers.\\ncreate or replace view public.shipper_rates_public\\nwith (security_invoker = true) as\\nselect\\n  r.id as rate_id,\\n  r.shipper_id,\\n  s.company_name,\\n  r.origin_region,\\n  r.origin_port,\\n  r.destination_country,\\n  r.vehicle_size_type,\\n  r.shipping_method,\\n  r.price,\\n  r.currency,\\n  s.payment_status\\nfrom public.shipping_rates r\\njoin public.shippers s on s.id = r.shipper_id\\nwhere r.active\\n  and s.status = ''approved''\\n  and s.payment_status <> ''suspended'';\\n\\n-- 4. purchase_requests.shipping_rate_id: give it a real FK (safe — the\\n-- column is always null today, confirmed unused anywhere in app/) and let\\n-- the buyer set/change it via the existing negotiation-guard trigger.\\nalter table public.purchase_requests\\n  add constraint purchase_requests_shipping_rate_id_fkey\\n  foreign key (shipping_rate_id) references public.shipping_rates(id);\\n\\ncreate or replace function public.purchase_requests_guard_negotiation()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n\\n  if exists (\\n    select 1 from public.vehicles v\\n    where v.id = old.vehicle_id and v.seller_id = auth.uid()\\n  ) then\\n    if old.negotiated_price_status <> ''accepted''\\n       and new.negotiated_price_status = ''proposed''\\n       and new.negotiated_price_usd is not null\\n       and new.negotiated_price_usd > 0\\n       and new.negotiated_price_usd < coalesce(\\n             old.vehicle_price_usd,\\n             (select price_usd from public.vehicles where id = old.vehicle_id)\\n           )\\n       and old.status in (''submitted'', ''under_review'', ''verified'')\\n    then\\n      new.negotiated_price_proposed_at := now();\\n      new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    else\\n      new.negotiated_price_usd := old.negotiated_price_usd;\\n      new.negotiated_price_status := old.negotiated_price_status;\\n      new.negotiated_price_proposed_at := old.negotiated_price_proposed_at;\\n      new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    end if;\\n\\n    new.vehicle_id := old.vehicle_id;\\n    new.buyer_id := old.buyer_id;\\n    new.shipping_rate_id := old.shipping_rate_id;\\n    new.status := old.status;\\n    new.vehicle_price_usd := old.vehicle_price_usd;\\n    new.mova_fee_usd := old.mova_fee_usd;\\n    new.mova_fee_payment_status := old.mova_fee_payment_status;\\n    new.mova_fee_stripe_session_id := old.mova_fee_stripe_session_id;\\n    new.mova_fee_checkout_url := old.mova_fee_checkout_url;\\n    new.seller_details_revealed_at := old.seller_details_revealed_at;\\n    new.seller_name := old.seller_name;\\n    new.seller_email := old.seller_email;\\n    new.seller_phone := old.seller_phone;\\n    new.seller_whatsapp := old.seller_whatsapp;\\n    new.payment_method := old.payment_method;\\n    new.payment_reference := old.payment_reference;\\n    new.bank_transfer_proof_path := old.bank_transfer_proof_path;\\n    new.bank_transfer_proof_uploaded_at := old.bank_transfer_proof_uploaded_at;\\n    new.bank_transfer_reviewed_by := old.bank_transfer_reviewed_by;\\n    new.bank_transfer_reviewed_at := old.bank_transfer_reviewed_at;\\n    new.bank_transfer_rejection_reason := old.bank_transfer_rejection_reason;\\n    new.notes := old.notes;\\n    new.assigned_admin_id := old.assigned_admin_id;\\n    new.created_at := old.created_at;\\n    return new;\\n  end if;\\n\\n  if old.buyer_id = auth.uid() then\\n    if old.negotiated_price_status = ''proposed''\\n       and new.negotiated_price_status = ''accepted''\\n    then\\n      new.negotiated_price_accepted_at := now();\\n      new.negotiated_price_usd := old.negotiated_price_usd;\\n      new.negotiated_price_proposed_at := old.negotiated_price_proposed_at;\\n    else\\n      new.negotiated_price_status := old.negotiated_price_status;\\n      new.negotiated_price_usd := old.negotiated_price_usd;\\n      new.negotiated_price_proposed_at := old.negotiated_price_proposed_at;\\n      new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    end if;\\n\\n    if old.mova_fee_payment_status in (''pending'', ''bank_transfer_rejected'')\\n       and new.mova_fee_payment_status = ''pending_manual_verification''\\n       and new.payment_method = ''bank_transfer''\\n       and new.bank_transfer_proof_path is not null\\n       and new.bank_transfer_proof_path is distinct from old.bank_transfer_proof_path\\n    then\\n      new.bank_transfer_proof_uploaded_at := now();\\n      new.bank_transfer_reviewed_by := null;\\n      new.bank_transfer_reviewed_at := null;\\n      new.bank_transfer_rejection_reason := null;\\n    else\\n      new.mova_fee_payment_status := old.mova_fee_payment_status;\\n      new.payment_method := old.payment_method;\\n      new.bank_transfer_proof_path := old.bank_transfer_proof_path;\\n      new.bank_transfer_proof_uploaded_at := old.bank_transfer_proof_uploaded_at;\\n      new.bank_transfer_reviewed_by := old.bank_transfer_reviewed_by;\\n      new.bank_transfer_reviewed_at := old.bank_transfer_reviewed_at;\\n      new.bank_transfer_rejection_reason := old.bank_transfer_rejection_reason;\\n    end if;\\n\\n    -- Shipping selection: freely settable (including back to null) while\\n    -- Invoice 1 hasn''t been generated yet, but only to an active rate whose\\n    -- vehicle_size_type matches this reservation''s vehicle — enforced here,\\n    -- not just in the UI, same as the negotiated-price ceiling above. Once\\n    -- mova_fee_checkout_url exists the pick is locked, mirroring how an\\n    -- accepted negotiated price locks.\\n    if old.mova_fee_checkout_url is null\\n       and new.shipping_rate_id is distinct from old.shipping_rate_id\\n       and (\\n         new.shipping_rate_id is null\\n         or exists (\\n           select 1\\n           from public.shipping_rates sr\\n           join public.vehicles v on v.id = old.vehicle_id\\n           where sr.id = new.shipping_rate_id\\n             and sr.active\\n             and sr.vehicle_size_type = v.vehicle_size_type\\n         )\\n       )\\n    then\\n      null;\\n    else\\n      new.shipping_rate_id := old.shipping_rate_id;\\n    end if;\\n\\n    new.vehicle_id := old.vehicle_id;\\n    new.buyer_id := old.buyer_id;\\n    new.status := old.status;\\n    new.vehicle_price_usd := old.vehicle_price_usd;\\n    new.mova_fee_usd := old.mova_fee_usd;\\n    new.mova_fee_stripe_session_id := old.mova_fee_stripe_session_id;\\n    new.mova_fee_checkout_url := old.mova_fee_checkout_url;\\n    new.seller_details_revealed_at := old.seller_details_revealed_at;\\n    new.seller_name := old.seller_name;\\n    new.seller_email := old.seller_email;\\n    new.seller_phone := old.seller_phone;\\n    new.seller_whatsapp := old.seller_whatsapp;\\n    new.payment_reference := old.payment_reference;\\n    new.notes := old.notes;\\n    new.assigned_admin_id := old.assigned_admin_id;\\n    new.created_at := old.created_at;\\n    return new;\\n  end if;\\n\\n  return old;\\nend;\\n$$;\\n"],"name":"shipping_rates_structure","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, '{"version":"20260917032515","statements":["alter type purchase_request_status add value ''expired'';"],"name":"purchase_request_expired_status","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260917032541","statements":["alter table public.purchase_requests\\n  add column fee_payment_requested_at timestamptz;\\n\\ncreate or replace function public.purchase_requests_guard_negotiation()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n\\n  if exists (\\n    select 1 from public.vehicles v\\n    where v.id = old.vehicle_id and v.seller_id = auth.uid()\\n  ) then\\n    if old.negotiated_price_status <> ''accepted''\\n       and new.negotiated_price_status = ''proposed''\\n       and new.negotiated_price_usd is not null\\n       and new.negotiated_price_usd > 0\\n       and new.negotiated_price_usd < coalesce(\\n             old.vehicle_price_usd,\\n             (select price_usd from public.vehicles where id = old.vehicle_id)\\n           )\\n       and old.status in (''submitted'', ''under_review'', ''verified'')\\n    then\\n      new.negotiated_price_proposed_at := now();\\n      new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    else\\n      new.negotiated_price_usd := old.negotiated_price_usd;\\n      new.negotiated_price_status := old.negotiated_price_status;\\n      new.negotiated_price_proposed_at := old.negotiated_price_proposed_at;\\n      new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    end if;\\n\\n    new.vehicle_id := old.vehicle_id;\\n    new.buyer_id := old.buyer_id;\\n    new.shipping_rate_id := old.shipping_rate_id;\\n    new.status := old.status;\\n    new.vehicle_price_usd := old.vehicle_price_usd;\\n    new.mova_fee_usd := old.mova_fee_usd;\\n    new.mova_fee_payment_status := old.mova_fee_payment_status;\\n    new.mova_fee_stripe_session_id := old.mova_fee_stripe_session_id;\\n    new.mova_fee_checkout_url := old.mova_fee_checkout_url;\\n    new.fee_payment_requested_at := old.fee_payment_requested_at;\\n    new.seller_details_revealed_at := old.seller_details_revealed_at;\\n    new.seller_name := old.seller_name;\\n    new.seller_email := old.seller_email;\\n    new.seller_phone := old.seller_phone;\\n    new.seller_whatsapp := old.seller_whatsapp;\\n    new.payment_method := old.payment_method;\\n    new.payment_reference := old.payment_reference;\\n    new.bank_transfer_proof_path := old.bank_transfer_proof_path;\\n    new.bank_transfer_proof_uploaded_at := old.bank_transfer_proof_uploaded_at;\\n    new.bank_transfer_reviewed_by := old.bank_transfer_reviewed_by;\\n    new.bank_transfer_reviewed_at := old.bank_transfer_reviewed_at;\\n    new.bank_transfer_rejection_reason := old.bank_transfer_rejection_reason;\\n    new.notes := old.notes;\\n    new.assigned_admin_id := old.assigned_admin_id;\\n    new.created_at := old.created_at;\\n    return new;\\n  end if;\\n\\n  if old.buyer_id = auth.uid() then\\n    if old.negotiated_price_status = ''proposed''\\n       and new.negotiated_price_status = ''accepted''\\n    then\\n      new.negotiated_price_accepted_at := now();\\n      new.negotiated_price_usd := old.negotiated_price_usd;\\n      new.negotiated_price_proposed_at := old.negotiated_price_proposed_at;\\n    else\\n      new.negotiated_price_status := old.negotiated_price_status;\\n      new.negotiated_price_usd := old.negotiated_price_usd;\\n      new.negotiated_price_proposed_at := old.negotiated_price_proposed_at;\\n      new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    end if;\\n\\n    if old.mova_fee_payment_status in (''pending'', ''bank_transfer_rejected'')\\n       and new.mova_fee_payment_status = ''pending_manual_verification''\\n       and new.payment_method = ''bank_transfer''\\n       and new.bank_transfer_proof_path is not null\\n       and new.bank_transfer_proof_path is distinct from old.bank_transfer_proof_path\\n    then\\n      new.bank_transfer_proof_uploaded_at := now();\\n      new.bank_transfer_reviewed_by := null;\\n      new.bank_transfer_reviewed_at := null;\\n      new.bank_transfer_rejection_reason := null;\\n    else\\n      new.mova_fee_payment_status := old.mova_fee_payment_status;\\n      new.payment_method := old.payment_method;\\n      new.bank_transfer_proof_path := old.bank_transfer_proof_path;\\n      new.bank_transfer_proof_uploaded_at := old.bank_transfer_proof_uploaded_at;\\n      new.bank_transfer_reviewed_by := old.bank_transfer_reviewed_by;\\n      new.bank_transfer_reviewed_at := old.bank_transfer_reviewed_at;\\n      new.bank_transfer_rejection_reason := old.bank_transfer_rejection_reason;\\n    end if;\\n\\n    if old.mova_fee_checkout_url is null\\n       and new.shipping_rate_id is distinct from old.shipping_rate_id\\n       and (\\n         new.shipping_rate_id is null\\n         or exists (\\n           select 1\\n           from public.shipping_rates sr\\n           join public.vehicles v on v.id = old.vehicle_id\\n           where sr.id = new.shipping_rate_id\\n             and sr.active\\n             and sr.vehicle_size_type = v.vehicle_size_type\\n         )\\n       )\\n    then\\n      null;\\n    else\\n      new.shipping_rate_id := old.shipping_rate_id;\\n    end if;\\n\\n    new.vehicle_id := old.vehicle_id;\\n    new.buyer_id := old.buyer_id;\\n    new.status := old.status;\\n    new.vehicle_price_usd := old.vehicle_price_usd;\\n    new.mova_fee_usd := old.mova_fee_usd;\\n    new.mova_fee_stripe_session_id := old.mova_fee_stripe_session_id;\\n    new.mova_fee_checkout_url := old.mova_fee_checkout_url;\\n    new.fee_payment_requested_at := old.fee_payment_requested_at;\\n    new.seller_details_revealed_at := old.seller_details_revealed_at;\\n    new.seller_name := old.seller_name;\\n    new.seller_email := old.seller_email;\\n    new.seller_phone := old.seller_phone;\\n    new.seller_whatsapp := old.seller_whatsapp;\\n    new.payment_reference := old.payment_reference;\\n    new.notes := old.notes;\\n    new.assigned_admin_id := old.assigned_admin_id;\\n    new.created_at := old.created_at;\\n    return new;\\n  end if;\\n\\n  return old;\\nend;\\n$$;"],"name":"auto_release_reservations","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260917032622","statements":["create extension if not exists pg_cron;\\ncreate extension if not exists pg_net;\\n\\nselect cron.schedule(\\n  ''release-abandoned-reservations'',\\n  ''*/15 * * * *'',\\n  $$\\n  select net.http_post(\\n    url := ''https://mova-marketplace.netlify.app/api/cron/release-reservations'',\\n    headers := jsonb_build_object(\\n      ''Content-Type'', ''application/json'',\\n      ''Authorization'',\\n      ''Bearer '' || (\\n        select decrypted_secret from vault.decrypted_secrets where name = ''cron_secret''\\n      )\\n    ),\\n    body := ''{}''::jsonb\\n  );\\n  $$\\n);"],"name":"release_reservations_cron","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
