insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260917045100","statements":["alter table public.vehicles\\n  add column title_photo_path text,\\n  add column title_identity_match_confirmed boolean not null default false;\\n\\nupdate public.vehicles\\n  set title_identity_match_confirmed = true\\n  where status = ''approved'';\\n\\ncreate or replace function public.vehicles_guard_admin_only_fields()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if public.is_admin() then\\n    return new;\\n  end if;\\n\\n  if tg_op = ''INSERT'' then\\n    new.vin_verification_status := ''unverified'';\\n    new.verification_status := ''unverified'';\\n    new.title_history_check_status := ''not_run'';\\n    new.title_identity_match_confirmed := false;\\n    new.rejection_reason := null;\\n    new.status := ''draft'';\\n    return new;\\n  end if;\\n\\n  new.vin_verification_status := old.vin_verification_status;\\n  new.verification_status := old.verification_status;\\n  new.title_history_check_status := old.title_history_check_status;\\n  new.title_identity_match_confirmed := old.title_identity_match_confirmed;\\n  new.rejection_reason := old.rejection_reason;\\n\\n  if not (old.status = ''draft'' and new.status = ''pending_review'') then\\n    new.status := old.status;\\n  end if;\\n\\n  return new;\\nend;\\n$$;\\n\\nalter table public.vehicles\\n  add constraint vehicles_title_identity_confirmed_before_approval\\n  check (not (status = ''approved'' and title_identity_match_confirmed = false));\\n\\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\\nvalues (\\n  ''vehicle-title-photos'',\\n  ''vehicle-title-photos'',\\n  false,\\n  10485760,\\n  array[''image/jpeg'', ''image/png'', ''image/webp'', ''application/pdf'']\\n)\\non conflict (id) do update set\\n  public = excluded.public,\\n  file_size_limit = excluded.file_size_limit,\\n  allowed_mime_types = excluded.allowed_mime_types;\\n\\ndrop policy if exists \\"vehicle title photos owner insert\\" on storage.objects;\\ncreate policy \\"vehicle title photos owner insert\\" on storage.objects\\n  for insert to authenticated\\n  with check (\\n    bucket_id = ''vehicle-title-photos''\\n    and (storage.foldername(name))[1] = (select auth.uid()::text)\\n  );\\n\\ndrop policy if exists \\"vehicle title photos owner update\\" on storage.objects;\\ncreate policy \\"vehicle title photos owner update\\" on storage.objects\\n  for update to authenticated\\n  using (\\n    bucket_id = ''vehicle-title-photos''\\n    and (storage.foldername(name))[1] = (select auth.uid()::text)\\n  )\\n  with check (\\n    bucket_id = ''vehicle-title-photos''\\n    and (storage.foldername(name))[1] = (select auth.uid()::text)\\n  );\\n\\ndrop policy if exists \\"vehicle title photos owner delete\\" on storage.objects;\\ncreate policy \\"vehicle title photos owner delete\\" on storage.objects\\n  for delete to authenticated\\n  using (\\n    bucket_id = ''vehicle-title-photos''\\n    and (storage.foldername(name))[1] = (select auth.uid()::text)\\n  );\\n\\ndrop policy if exists \\"vehicle title photos owner read\\" on storage.objects;\\ncreate policy \\"vehicle title photos owner read\\" on storage.objects\\n  for select to authenticated\\n  using (\\n    bucket_id = ''vehicle-title-photos''\\n    and (\\n      (storage.foldername(name))[1] = (select auth.uid()::text)\\n      or public.is_admin()\\n    )\\n  );"],"name":"title_identity_checklist","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260917131703","statements":["create table public.rate_limit_hits (\\n  id bigint generated always as identity primary key,\\n  bucket_key text not null,\\n  created_at timestamptz not null default now()\\n);\\n\\ncreate index rate_limit_hits_bucket_created_idx\\n  on public.rate_limit_hits (bucket_key, created_at);\\n\\nalter table public.rate_limit_hits enable row level security;\\n\\ncreate or replace function public.check_rate_limit(\\n  p_bucket_key text,\\n  p_max_count int,\\n  p_window_seconds int\\n) returns boolean\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\ndeclare\\n  v_count int;\\nbegin\\n  delete from public.rate_limit_hits\\n    where bucket_key = p_bucket_key\\n      and created_at < now() - make_interval(secs => p_window_seconds);\\n\\n  select count(*) into v_count from public.rate_limit_hits\\n    where bucket_key = p_bucket_key;\\n\\n  if v_count >= p_max_count then\\n    return false;\\n  end if;\\n\\n  insert into public.rate_limit_hits (bucket_key) values (p_bucket_key);\\n  return true;\\nend;\\n$$;\\n\\nrevoke all on function public.check_rate_limit(text, int, int) from public, anon, authenticated;\\ngrant execute on function public.check_rate_limit(text, int, int) to service_role;"],"name":"rate_limiting","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260917143408","statements":["select cron.schedule(\\n  ''release-abandoned-reservations'',\\n  ''*/15 * * * *'',\\n  $$\\n  select net.http_post(\\n    url := ''https://mova-marketplace.netlify.app/api/cron/release-reservations'',\\n    headers := jsonb_build_object(\\n      ''Content-Type'', ''application/json'',\\n      ''Authorization'',\\n      ''Bearer '' || (\\n        select decrypted_secret from vault.decrypted_secrets where name = ''cron_secret''\\n      )\\n    ),\\n    body := ''{}''::jsonb,\\n    timeout_milliseconds := 15000\\n  );\\n  $$\\n);"],"name":"release_reservations_cron_timeout","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260918050802","statements":["create or replace function public.vehicle_photos_prevent_empty()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\ndeclare\\n  v_vehicle_id uuid;\\nbegin\\n  for v_vehicle_id in select distinct vehicle_id from old_rows loop\\n    if not exists (select 1 from public.vehicle_photos where vehicle_id = v_vehicle_id) then\\n      raise exception ''A listing must have at least one photo.'';\\n    end if;\\n  end loop;\\n  return null;\\nend;\\n$$;\\n\\ndrop trigger if exists vehicle_photos_prevent_empty_trigger on public.vehicle_photos;\\ncreate trigger vehicle_photos_prevent_empty_trigger\\n  after delete on public.vehicle_photos\\n  referencing old table as old_rows\\n  for each statement\\n  execute function public.vehicle_photos_prevent_empty();"],"name":"vehicle_photos_min_one","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260918050843","statements":["create or replace function public.vehicle_photos_prevent_empty()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\ndeclare\\n  v_vehicle_id uuid;\\nbegin\\n  for v_vehicle_id in select distinct vehicle_id from old_rows loop\\n    if exists (select 1 from public.vehicles where id = v_vehicle_id)\\n       and not exists (select 1 from public.vehicle_photos where vehicle_id = v_vehicle_id)\\n    then\\n      raise exception ''A listing must have at least one photo.'';\\n    end if;\\n  end loop;\\n  return null;\\nend;\\n$$;"],"name":"vehicle_photos_min_one_fix_cascade","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260918172325","statements":["-- MOVA — Mandatory Terms & Conditions acceptance\\n--\\n-- Independent from public.policy_acceptances (the Buyer Protection & Refund\\n-- Policy''s audit log) — a user must accept both, not one instead of the\\n-- other. A new table rather than a new policy_acceptances.policy_type value\\n-- because that table''s shape is specific to BPP: its `role` column is typed\\n-- `user_role`, which has no ''shipper'' value (shippers are a separate\\n-- public.shippers row, optionally linked to a plain buyer/seller-role\\n-- public.users account — see claimShipper() in app/shipper/actions.ts), and\\n-- its `context` enum + CHECK constraint tie ''fee_payment'' to a\\n-- purchase_request_id, which doesn''t fit T&C''s own two contexts.\\n--\\n-- Same immutability shape as policy_acceptances: append-only audit log,\\n-- BEFORE INSERT guard trigger force-stamps accepted_at/role server-side, no\\n-- update/delete RLS policy for anyone (admin included).\\n--\\n-- No denormalized \\"current acceptance\\" snapshot on public.users — querying\\n-- this table directly by (user_id, version) is a single indexed lookup, and\\n-- avoids extending users_guard_admin_only_fields() to protect a new pair of\\n-- columns just to let a trusted insert path bypass that same guard.\\n\\ncreate type terms_acceptance_context as enum (''signup'', ''login_gate'');\\n\\ncreate table public.terms_acceptances (\\n  id uuid primary key default uuid_generate_v4(),\\n  user_id uuid not null references public.users(id) on delete cascade,\\n  -- Derived server-side from public.users at insert time — see the guard\\n  -- trigger below. Never trusted from the caller. Audit context only (e.g.\\n  -- \\"were they a seller when they accepted\\") — not used for gating.\\n  role user_role not null,\\n  context terms_acceptance_context not null,\\n  version text not null,\\n  -- Captured server-side (request headers), never client-supplied.\\n  ip_address text,\\n  user_agent text,\\n  accepted_at timestamptz not null default now()\\n);\\n\\n-- Hot path: \\"does this user have a row for the current version\\" — checked by\\n-- middleware on every authenticated request.\\ncreate index terms_acceptances_user_version_idx\\n  on public.terms_acceptances (user_id, version);\\n-- Cold path: admin/audit \\"most recent acceptance for this user\\".\\ncreate index terms_acceptances_user_idx\\n  on public.terms_acceptances (user_id, accepted_at desc);\\n\\nalter table public.terms_acceptances enable row level security;\\n\\ncreate policy \\"terms acceptances self or admin read\\" on public.terms_acceptances\\n  for select using (user_id = auth.uid() or public.is_admin());\\n\\ncreate policy \\"terms acceptances self insert\\" on public.terms_acceptances\\n  for insert with check (user_id = auth.uid());\\n-- Deliberately no update/delete policy for anyone, admin included —\\n-- immutable/append-only.\\n\\ncreate or replace function public.terms_acceptances_guard()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  new.accepted_at := now();\\n  select role into new.role from public.users where id = new.user_id;\\n  return new;\\nend;\\n$$;\\n\\ncreate trigger terms_acceptances_guard\\n  before insert on public.terms_acceptances\\n  for each row execute procedure public.terms_acceptances_guard();\\n\\nrevoke execute on function public.terms_acceptances_guard()\\n  from public, anon, authenticated;\\n"],"name":"terms_and_conditions","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260921095024","statements":["-- MOVA — Title-ownership verification: authorized-seller path + audit trail\\n--\\n-- Extends the title-photo/identity-match checklist already built in 0023\\n-- (public.vehicles.title_photo_path / title_identity_match_confirmed, the\\n-- private vehicle-title-photos bucket, and the\\n-- vehicles_title_identity_confirmed_before_approval CHECK). This migration\\n-- adds what was still missing: required title upload before pending_review,\\n-- an authorized-seller (not_titled_owner) declaration + authorization\\n-- document path, a real audit trail on title_identity_match_confirmed, and\\n-- confirmation-reset on document/declaration change.\\n\\ncreate or replace function public.seller_profiles_guard_admin_only_fields()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n\\n  if tg_op = ''INSERT'' then\\n    new.verification_status := ''unverified'';\\n    new.id_verified_at := null;\\n    new.full_name := null;\\n    if new.id_verification_status <> ''pending'' then\\n      new.id_verification_status := ''unverified'';\\n    end if;\\n    return new;\\n  end if;\\n\\n  new.verification_status := old.verification_status;\\n  new.id_verified_at := old.id_verified_at;\\n  new.full_name := old.full_name;\\n  if new.id_verification_status <> ''pending'' then\\n    new.id_verification_status := old.id_verification_status;\\n  end if;\\n  return new;\\nend;\\n$$;\\n\\nalter table public.vehicles\\n  add column not_titled_owner boolean not null default false,\\n  add column authorization_document_path text,\\n  add column title_identity_match_confirmed_by uuid references public.users(id),\\n  add column title_identity_match_confirmed_at timestamptz;\\n\\nalter table public.vehicles disable trigger vehicles_guard_admin_only_fields;\\n\\nupdate public.vehicles\\n  set status = ''draft''\\n  where status = ''pending_review'' and title_photo_path is null;\\n\\nalter table public.vehicles enable trigger vehicles_guard_admin_only_fields;\\n\\ncreate or replace function public.vehicles_guard_admin_only_fields()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if public.is_admin() then\\n    return new;\\n  end if;\\n\\n  if tg_op = ''INSERT'' then\\n    new.vin_verification_status := ''unverified'';\\n    new.verification_status := ''unverified'';\\n    new.title_history_check_status := ''not_run'';\\n    new.title_identity_match_confirmed := false;\\n    new.title_identity_match_confirmed_by := null;\\n    new.title_identity_match_confirmed_at := null;\\n    new.rejection_reason := null;\\n    new.status := ''draft'';\\n    return new;\\n  end if;\\n\\n  if new.title_photo_path is distinct from old.title_photo_path\\n     or new.not_titled_owner is distinct from old.not_titled_owner\\n     or new.authorization_document_path is distinct from old.authorization_document_path\\n  then\\n    new.title_identity_match_confirmed := false;\\n    new.title_identity_match_confirmed_by := null;\\n    new.title_identity_match_confirmed_at := null;\\n  else\\n    new.title_identity_match_confirmed := old.title_identity_match_confirmed;\\n    new.title_identity_match_confirmed_by := old.title_identity_match_confirmed_by;\\n    new.title_identity_match_confirmed_at := old.title_identity_match_confirmed_at;\\n  end if;\\n\\n  new.vin_verification_status := old.vin_verification_status;\\n  new.verification_status := old.verification_status;\\n  new.title_history_check_status := old.title_history_check_status;\\n  new.rejection_reason := old.rejection_reason;\\n\\n  if not (old.status = ''draft'' and new.status = ''pending_review'') then\\n    new.status := old.status;\\n  end if;\\n\\n  return new;\\nend;\\n$$;\\n\\nalter table public.vehicles\\n  add constraint vehicles_title_photo_required_before_review\\n  check (status <> ''pending_review'' or title_photo_path is not null);\\n\\nalter table public.vehicles\\n  add constraint vehicles_authorization_doc_required_before_review\\n  check (\\n    status <> ''pending_review''\\n    or not not_titled_owner\\n    or authorization_document_path is not null\\n  );\\n"],"name":"title_ownership_verification","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260923045637","statements":["create table public.privacy_policy_acceptances (\\n  id uuid primary key default uuid_generate_v4(),\\n  user_id uuid not null references public.users(id) on delete cascade,\\n  role user_role not null,\\n  context terms_acceptance_context not null,\\n  version text not null,\\n  ip_address text,\\n  user_agent text,\\n  accepted_at timestamptz not null default now()\\n);\\n\\ncreate index privacy_policy_acceptances_user_version_idx\\n  on public.privacy_policy_acceptances (user_id, version);\\ncreate index privacy_policy_acceptances_user_idx\\n  on public.privacy_policy_acceptances (user_id, accepted_at desc);\\n\\nalter table public.privacy_policy_acceptances enable row level security;\\n\\ncreate policy \\"privacy policy acceptances self or admin read\\" on public.privacy_policy_acceptances\\n  for select using (user_id = auth.uid() or public.is_admin());\\n\\ncreate policy \\"privacy policy acceptances self insert\\" on public.privacy_policy_acceptances\\n  for insert with check (user_id = auth.uid());\\n\\ncreate or replace function public.privacy_policy_acceptances_guard()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  new.accepted_at := now();\\n  select role into new.role from public.users where id = new.user_id;\\n  return new;\\nend;\\n$$;\\n\\ncreate trigger privacy_policy_acceptances_guard\\n  before insert on public.privacy_policy_acceptances\\n  for each row execute procedure public.privacy_policy_acceptances_guard();\\n\\nrevoke execute on function public.privacy_policy_acceptances_guard()\\n  from public, anon, authenticated;\\n"],"name":"privacy_policy_acceptance","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260927201519","statements":["alter table public.vehicles disable trigger vehicles_guard_admin_only_fields;\\n\\nupdate public.vehicles\\n  set title_identity_match_confirmed = false,\\n      title_identity_match_confirmed_by = null,\\n      title_identity_match_confirmed_at = null\\n  where title_identity_match_confirmed\\n    and not (\\n      title_identity_match_confirmed_at is not null\\n      and (\\n        title_photo_path is not null\\n        or (not_titled_owner and authorization_document_path is not null)\\n      )\\n    );\\n\\nalter table public.vehicles enable trigger vehicles_guard_admin_only_fields;\\n\\nalter table public.vehicles\\n  add constraint vehicles_title_confirmation_requires_document\\n  check (\\n    not title_identity_match_confirmed\\n    or (\\n      title_identity_match_confirmed_at is not null\\n      and (\\n        title_photo_path is not null\\n        or (not_titled_owner and authorization_document_path is not null)\\n      )\\n    )\\n  );\\n\\ncreate or replace function public.vehicle_has_title_document(v public.vehicles)\\nreturns boolean\\nlanguage sql\\nstable\\nset search_path = public\\nas $$\\n  select v.title_photo_path is not null;\\n$$;\\n\\ncreate or replace function public.vehicle_has_authorization_document(v public.vehicles)\\nreturns boolean\\nlanguage sql\\nstable\\nset search_path = public\\nas $$\\n  select v.authorization_document_path is not null;\\n$$;\\n\\ncreate or replace function public.vehicle_seller_identity_verified(v public.vehicles)\\nreturns boolean\\nlanguage sql\\nstable\\nsecurity definer\\nset search_path = public\\nas $$\\n  select exists (\\n    select 1 from public.seller_profiles sp\\n    where sp.user_id = v.seller_id\\n      and sp.id_verification_status = ''verified''\\n  );\\n$$;\\n\\ngrant execute on function public.vehicle_has_title_document(public.vehicles) to anon, authenticated;\\ngrant execute on function public.vehicle_has_authorization_document(public.vehicles) to anon, authenticated;\\ngrant execute on function public.vehicle_seller_identity_verified(public.vehicles) to anon, authenticated;"],"name":"title_review_badge_integrity","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260927203406","statements":["create or replace function public.vehicles_guard_admin_only_fields()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\ndeclare\\n  documents_changed boolean := false;\\nbegin\\n  if public.is_admin() then\\n    return new;\\n  end if;\\n\\n  if tg_op = ''INSERT'' then\\n    new.vin_verification_status := ''unverified'';\\n    new.verification_status := ''unverified'';\\n    new.title_history_check_status := ''not_run'';\\n    new.title_identity_match_confirmed := false;\\n    new.title_identity_match_confirmed_by := null;\\n    new.title_identity_match_confirmed_at := null;\\n    new.rejection_reason := null;\\n    new.status := ''draft'';\\n    return new;\\n  end if;\\n\\n  documents_changed :=\\n    new.title_photo_path is distinct from old.title_photo_path\\n    or new.not_titled_owner is distinct from old.not_titled_owner\\n    or new.authorization_document_path is distinct from old.authorization_document_path;\\n\\n  if documents_changed then\\n    new.title_identity_match_confirmed := false;\\n    new.title_identity_match_confirmed_by := null;\\n    new.title_identity_match_confirmed_at := null;\\n  else\\n    new.title_identity_match_confirmed := old.title_identity_match_confirmed;\\n    new.title_identity_match_confirmed_by := old.title_identity_match_confirmed_by;\\n    new.title_identity_match_confirmed_at := old.title_identity_match_confirmed_at;\\n  end if;\\n\\n  new.vin_verification_status := old.vin_verification_status;\\n  new.verification_status := old.verification_status;\\n  new.title_history_check_status := old.title_history_check_status;\\n  new.rejection_reason := old.rejection_reason;\\n\\n  if documents_changed and old.status = ''approved'' then\\n    new.status := ''pending_review'';\\n  elsif not (old.status = ''draft'' and new.status = ''pending_review'') then\\n    new.status := old.status;\\n  end if;\\n\\n  return new;\\nend;\\n$$;"],"name":"title_swap_returns_to_review","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260927204015","statements":["create table public.blocked_vins (\\n  vin text primary key,\\n  note text,\\n  created_at timestamptz not null default now()\\n);\\n\\ncomment on table public.blocked_vins is\\n  ''Sample/demo VINs that must never be listed. Mirrors BLOCKED_SAMPLE_VINS in lib/vin.ts; keep both in sync.'';\\n\\ninsert into public.blocked_vins (vin, note) values\\n  (''1HGCM82633A004352'', ''2003 Honda Accord — NHTSA vPIC''''s own sample VIN; was also this app''''s form placeholder''),\\n  (''1HGBH41JXMN109186'', ''Honda sample VIN used across API docs and test data''),\\n  (''JH4TB2H26CC000000'', ''Acura sample VIN (NHTSA decoder examples)''),\\n  (''WBA3A5C55CF256691'', ''BMW sample VIN in common circulation''),\\n  (''3VWFE21C04M000123'', ''VW sample VIN in common circulation''),\\n  (''WVWZZZ3BZWE689725'', ''VW Passat sample VIN (European docs)''),\\n  (''1M8GDM9AXKP042788'', ''NHTSA check-digit worked example''),\\n  (''11111111111111111'', ''placeholder''),\\n  (''12345678901234567'', ''placeholder'');\\n\\nalter table public.blocked_vins enable row level security;\\n\\ncreate policy \\"blocked vins public read\\" on public.blocked_vins\\n  for select using (true);\\n\\ncreate policy \\"blocked vins admin write\\" on public.blocked_vins\\n  for all using (public.is_admin()) with check (public.is_admin());\\n\\ncreate or replace function public.vin_check_digit(vin text)\\nreturns text\\nlanguage plpgsql\\nimmutable\\nset search_path = public\\nas $$\\ndeclare\\n  weights int[] := array[8,7,6,5,4,3,2,10,0,9,8,7,6,5,4,3,2];\\n  total int := 0;\\n  ch text;\\n  val int;\\n  i int;\\n  remainder int;\\nbegin\\n  if vin is null or length(vin) <> 17 then\\n    return null;\\n  end if;\\n\\n  for i in 1..17 loop\\n    ch := substr(vin, i, 1);\\n    val := case\\n      when ch between ''0'' and ''9'' then ch::int\\n      when ch in (''A'',''J'') then 1\\n      when ch in (''B'',''K'',''S'') then 2\\n      when ch in (''C'',''L'',''T'') then 3\\n      when ch in (''D'',''M'',''U'') then 4\\n      when ch in (''E'',''N'',''V'') then 5\\n      when ch in (''F'',''W'') then 6\\n      when ch in (''G'',''P'',''X'') then 7\\n      when ch in (''H'',''Y'') then 8\\n      when ch in (''R'',''Z'') then 9\\n      else 0\\n    end;\\n    total := total + val * weights[i];\\n  end loop;\\n\\n  remainder := total % 11;\\n  return case when remainder = 10 then ''X'' else remainder::text end;\\nend;\\n$$;\\n\\ncreate or replace function public.vin_is_sequential(vin text)\\nreturns boolean\\nlanguage plpgsql\\nimmutable\\nset search_path = public\\nas $$\\ndeclare\\n  alphabet text := ''0123456789ABCDEFGHJKLMNPRSTUVWXYZ'';\\n  n int := 33;\\n  asc_run int := 1;\\n  desc_run int := 1;\\n  longest_asc int := 1;\\n  longest_desc int := 1;\\n  prev int;\\n  cur int;\\n  step int;\\n  i int;\\nbegin\\n  if vin is null or length(vin) <> 17 then\\n    return false;\\n  end if;\\n\\n  prev := position(substr(vin, 1, 1) in alphabet) - 1;\\n  if prev < 0 then\\n    return false;\\n  end if;\\n\\n  for i in 2..17 loop\\n    cur := position(substr(vin, i, 1) in alphabet) - 1;\\n    if cur < 0 then\\n      return false;\\n    end if;\\n    step := ((cur - prev) % n + n) % n;\\n    asc_run := case when step = 1 then asc_run + 1 else 1 end;\\n    desc_run := case when step = n - 1 then desc_run + 1 else 1 end;\\n    longest_asc := greatest(longest_asc, asc_run);\\n    longest_desc := greatest(longest_desc, desc_run);\\n    prev := cur;\\n  end loop;\\n\\n  return greatest(longest_asc, longest_desc) >= 12;\\nend;\\n$$;\\n\\ncreate or replace function public.vin_is_valid(vin text)\\nreturns boolean\\nlanguage plpgsql\\nstable\\nset search_path = public\\nas $$\\ndeclare\\n  v text;\\nbegin\\n  if vin is null then\\n    return false;\\n  end if;\\n\\n  v := upper(btrim(vin));\\n\\n  if v !~ ''^[A-HJ-NPR-Z0-9]{17}$'' then\\n    return false;\\n  end if;\\n\\n  if exists (select 1 from public.blocked_vins b where upper(b.vin) = v) then\\n    return false;\\n  end if;\\n\\n  if length(regexp_replace(v, ''(.)\\\\1*'', ''\\\\1'', ''g'')) = 1 then\\n    return false;\\n  end if;\\n\\n  if public.vin_is_sequential(v) then\\n    return false;\\n  end if;\\n\\n  if v ~ ''^[1-5]'' and public.vin_check_digit(v) is distinct from substr(v, 9, 1) then\\n    return false;\\n  end if;\\n\\n  return true;\\nend;\\n$$;\\n\\ngrant execute on function public.vin_check_digit(text) to anon, authenticated;\\ngrant execute on function public.vin_is_sequential(text) to anon, authenticated;\\ngrant execute on function public.vin_is_valid(text) to anon, authenticated;\\n\\nalter table public.vehicles\\n  add constraint vehicles_vin_valid\\n  check (public.vin_is_valid(vin)) not valid;"],"name":"vin_validation","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260927205342","statements":["create or replace function public.vehicle_has_active_buyer(p_vehicle_id uuid)\\nreturns boolean\\nlanguage sql\\nstable\\nsecurity definer\\nset search_path = public\\nas $$\\n  select exists (\\n    select 1 from public.purchase_requests pr\\n    where pr.vehicle_id = p_vehicle_id\\n      and (\\n        pr.status in (''submitted'', ''under_review'', ''verified'')\\n        or (\\n          pr.mova_fee_payment_status in (''paid'', ''pending_manual_verification'')\\n          and pr.status <> ''completed''\\n        )\\n      )\\n  );\\n$$;\\n\\nrevoke execute on function public.vehicle_has_active_buyer(uuid) from public;\\ngrant execute on function public.vehicle_has_active_buyer(uuid) to authenticated;\\n\\ncreate or replace function public.vehicles_guard_admin_only_fields()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\ndeclare\\n  documents_changed boolean := false;\\n  archiving boolean := false;\\nbegin\\n  if public.is_admin() then\\n    return new;\\n  end if;\\n\\n  if tg_op = ''INSERT'' then\\n    new.vin_verification_status := ''unverified'';\\n    new.verification_status := ''unverified'';\\n    new.title_history_check_status := ''not_run'';\\n    new.title_identity_match_confirmed := false;\\n    new.title_identity_match_confirmed_by := null;\\n    new.title_identity_match_confirmed_at := null;\\n    new.rejection_reason := null;\\n    new.status := ''draft'';\\n    return new;\\n  end if;\\n\\n  documents_changed :=\\n    new.title_photo_path is distinct from old.title_photo_path\\n    or new.not_titled_owner is distinct from old.not_titled_owner\\n    or new.authorization_document_path is distinct from old.authorization_document_path;\\n\\n  if documents_changed then\\n    new.title_identity_match_confirmed := false;\\n    new.title_identity_match_confirmed_by := null;\\n    new.title_identity_match_confirmed_at := null;\\n  else\\n    new.title_identity_match_confirmed := old.title_identity_match_confirmed;\\n    new.title_identity_match_confirmed_by := old.title_identity_match_confirmed_by;\\n    new.title_identity_match_confirmed_at := old.title_identity_match_confirmed_at;\\n  end if;\\n\\n  new.vin_verification_status := old.vin_verification_status;\\n  new.verification_status := old.verification_status;\\n  new.title_history_check_status := old.title_history_check_status;\\n  new.rejection_reason := old.rejection_reason;\\n\\n  archiving := new.status = ''archived''\\n    and old.status in (''draft'', ''pending_review'', ''approved'', ''rejected'');\\n\\n  if archiving and public.vehicle_has_active_buyer(old.id) then\\n    raise exception ''vehicle_has_active_buyer''\\n      using errcode = ''check_violation'',\\n            hint = ''This car has an active buyer, contact MOVA on WhatsApp to cancel.'';\\n  end if;\\n\\n  if archiving then\\n    new.status := ''archived'';\\n  elsif documents_changed and old.status = ''approved'' then\\n    new.status := ''pending_review'';\\n  elsif not (old.status = ''draft'' and new.status = ''pending_review'') then\\n    new.status := old.status;\\n  end if;\\n\\n  return new;\\nend;\\n$$;"],"name":"seller_can_archive_own_listing","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260928160600","statements":["alter table public.vehicles\\n  add column vin_masked text\\n    generated always as (public.mask_vin(vin, 6)) stored,\\n  add column has_title_document boolean not null\\n    generated always as (title_photo_path is not null) stored,\\n  add column has_authorization_document boolean not null\\n    generated always as (authorization_document_path is not null) stored,\\n  add column seller_identity_verified boolean not null default false;\\n\\ncreate or replace function public.seller_is_identity_verified(p_seller_id uuid)\\nreturns boolean\\nlanguage sql\\nstable\\nsecurity definer\\nset search_path = public\\nas $$\\n  select exists (\\n    select 1 from public.seller_profiles sp\\n    where sp.user_id = p_seller_id\\n      and sp.id_verification_status = ''verified''\\n  );\\n$$;\\n\\nrevoke execute on function public.seller_is_identity_verified(uuid) from public, anon, authenticated;\\n\\nalter table public.vehicles disable trigger vehicles_guard_admin_only_fields;\\nupdate public.vehicles v\\n   set seller_identity_verified = public.seller_is_identity_verified(v.seller_id)\\n where public.vin_is_valid(v.vin);\\nalter table public.vehicles enable trigger vehicles_guard_admin_only_fields;\\n\\ncreate or replace function public.vehicles_guard_admin_only_fields()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\ndeclare\\n  documents_changed boolean := false;\\n  archiving boolean := false;\\nbegin\\n  new.seller_identity_verified := public.seller_is_identity_verified(new.seller_id);\\n\\n  if public.is_admin() then\\n    return new;\\n  end if;\\n\\n  if tg_op = ''INSERT'' then\\n    new.vin_verification_status := ''unverified'';\\n    new.verification_status := ''unverified'';\\n    new.title_history_check_status := ''not_run'';\\n    new.title_identity_match_confirmed := false;\\n    new.title_identity_match_confirmed_by := null;\\n    new.title_identity_match_confirmed_at := null;\\n    new.rejection_reason := null;\\n    new.status := ''draft'';\\n    return new;\\n  end if;\\n\\n  documents_changed :=\\n    new.title_photo_path is distinct from old.title_photo_path\\n    or new.not_titled_owner is distinct from old.not_titled_owner\\n    or new.authorization_document_path is distinct from old.authorization_document_path;\\n\\n  if documents_changed then\\n    new.title_identity_match_confirmed := false;\\n    new.title_identity_match_confirmed_by := null;\\n    new.title_identity_match_confirmed_at := null;\\n  else\\n    new.title_identity_match_confirmed := old.title_identity_match_confirmed;\\n    new.title_identity_match_confirmed_by := old.title_identity_match_confirmed_by;\\n    new.title_identity_match_confirmed_at := old.title_identity_match_confirmed_at;\\n  end if;\\n\\n  new.vin_verification_status := old.vin_verification_status;\\n  new.verification_status := old.verification_status;\\n  new.title_history_check_status := old.title_history_check_status;\\n  new.rejection_reason := old.rejection_reason;\\n\\n  -- Seller-initiated withdrawal. Raises rather than silently reverting,\\n  -- because the seller asked for something specific and needs to know it\\n  -- didn''t happen — unlike the catch-all revert below, which exists to\\n  -- neutralise writes the seller never intended to make.\\n  archiving := new.status = ''archived''\\n    and old.status in (''draft'', ''pending_review'', ''approved'', ''rejected'');\\n\\n  if archiving and public.vehicle_has_active_buyer(old.id) then\\n    raise exception ''vehicle_has_active_buyer''\\n      using errcode = ''check_violation'',\\n            hint = ''This car has an active buyer, contact MOVA on WhatsApp to cancel.'';\\n  end if;\\n\\n  if archiving then\\n    new.status := ''archived'';\\n  elsif documents_changed and old.status = ''approved'' then\\n    new.status := ''pending_review'';\\n  elsif not (old.status = ''draft'' and new.status = ''pending_review'') then\\n    new.status := old.status;\\n  end if;\\n\\n  return new;\\nend;\\n$$;\\n\\ncreate or replace function public.seller_profiles_sync_vehicle_identity()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\ndeclare\\n  verified boolean := new.id_verification_status = ''verified'';\\nbegin\\n  update public.vehicles\\n     set seller_identity_verified = verified\\n   where seller_id = new.user_id\\n     and seller_identity_verified is distinct from verified\\n     -- See the backfill note: an invalid-VIN legacy row can''t be updated,\\n     -- and failing here would fail the seller_profiles write with it.\\n     and public.vin_is_valid(vin);\\n  return null;\\nend;\\n$$;\\n\\nrevoke execute on function public.seller_profiles_sync_vehicle_identity() from public, anon, authenticated;\\n\\ncreate trigger seller_profiles_sync_vehicle_identity\\n  after insert or update of id_verification_status on public.seller_profiles\\n  for each row execute procedure public.seller_profiles_sync_vehicle_identity();\\n\\ncreate or replace function public.vehicle_vin(p_vehicle_id uuid)\\nreturns text\\nlanguage sql\\nstable\\nsecurity definer\\nset search_path = public\\nas $$\\n  select v.vin\\n  from public.vehicles v\\n  where v.id = p_vehicle_id\\n    and auth.uid() is not null\\n    and (\\n      public.is_admin()\\n      or v.seller_id = auth.uid()\\n      or exists (\\n        select 1 from public.purchase_requests pr\\n        where pr.vehicle_id = v.id\\n          and pr.buyer_id = auth.uid()\\n          and pr.mova_fee_payment_status = ''paid''\\n          and pr.seller_details_revealed_at is not null\\n      )\\n    );\\n$$;\\n\\nrevoke execute on function public.vehicle_vin(uuid) from public, anon;\\ngrant execute on function public.vehicle_vin(uuid) to authenticated;"],"name":"vehicle_private_columns","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260928165844","statements":["revoke select on public.vehicles from anon, authenticated;\\n\\ndo $$\\ndeclare\\n  cols text;\\nbegin\\n  select string_agg(quote_ident(column_name), '', '' order by ordinal_position)\\n    into cols\\n    from information_schema.columns\\n   where table_schema = ''public''\\n     and table_name = ''vehicles''\\n     and column_name not in (''vin'', ''title_photo_path'', ''authorization_document_path'');\\n  execute format(''grant select (%s) on public.vehicles to anon, authenticated'', cols);\\nend;\\n$$;"],"name":"vehicles_column_level_select","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260928213228","statements":["drop function public.vehicle_vin_display(public.vehicles);\\ndrop function public.vehicle_has_title_document(public.vehicles);\\ndrop function public.vehicle_has_authorization_document(public.vehicles);\\ndrop function public.vehicle_seller_identity_verified(public.vehicles);"],"name":"drop_vehicle_computed_columns","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260928214850","statements":["create table public.platform_settings (\\n  id boolean primary key default true check (id),\\n  prelaunch boolean not null default true,\\n  updated_at timestamptz not null default now()\\n);\\n\\ninsert into public.platform_settings (id, prelaunch) values (true, true);\\n\\nalter table public.platform_settings enable row level security;\\n\\ncreate policy \\"platform settings public read\\" on public.platform_settings\\n  for select using (true);\\ncreate policy \\"platform settings admin update\\" on public.platform_settings\\n  for update using (public.is_admin()) with check (public.is_admin());\\n\\ncreate or replace function public.is_prelaunch()\\nreturns boolean\\nlanguage sql\\nstable\\nsecurity definer\\nset search_path = public\\nas $$\\n  select coalesce((select prelaunch from public.platform_settings where id), true);\\n$$;\\n\\ngrant execute on function public.is_prelaunch() to anon, authenticated;\\n\\ncreate or replace function public.purchase_requests_prelaunch_guard()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if not public.is_prelaunch()\\n     or public.is_admin()\\n     or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n\\n  if tg_op = ''INSERT'' then\\n    raise exception ''prelaunch_reservations_closed''\\n      using errcode = ''check_violation'',\\n            hint = ''MOVA is launching soon and is not taking reservations yet.'';\\n  end if;\\n\\n  if new.mova_fee_payment_status is distinct from old.mova_fee_payment_status\\n     or new.payment_method is distinct from old.payment_method\\n     or new.bank_transfer_proof_path is distinct from old.bank_transfer_proof_path then\\n    raise exception ''prelaunch_payments_closed''\\n      using errcode = ''check_violation'',\\n            hint = ''MOVA is launching soon and is not taking payments yet.'';\\n  end if;\\n\\n  return new;\\nend;\\n$$;\\n\\nrevoke execute on function public.purchase_requests_prelaunch_guard() from public, anon, authenticated;\\n\\ncreate trigger purchase_requests_prelaunch_guard\\n  before insert or update on public.purchase_requests\\n  for each row execute procedure public.purchase_requests_prelaunch_guard();\\n\\ncreate table public.waitlist_signups (\\n  id uuid primary key default gen_random_uuid(),\\n  email text check (\\n    email is null\\n    or (length(email) <= 254 and email ~ ''^[^@[:space:]]+@[^@[:space:]]+\\\\.[^@[:space:]]+$'')\\n  ),\\n  whatsapp text check (\\n    whatsapp is null or whatsapp ~ ''^\\\\+?[0-9][0-9 ()-]{6,19}$''\\n  ),\\n  country text not null check (country in (''NG'', ''GH'', ''TG'', ''BJ'', ''OTHER'')),\\n  vehicle_id uuid references public.vehicles(id) on delete set null,\\n  source text not null default ''site'' check (source in (''site'', ''listing'', ''dashboard'')),\\n  created_at timestamptz not null default now(),\\n  constraint waitlist_signups_contact_required check (email is not null or whatsapp is not null)\\n);\\n\\ncreate index waitlist_signups_created_idx on public.waitlist_signups (created_at desc);\\n\\nalter table public.waitlist_signups enable row level security;\\n\\ncreate policy \\"waitlist anyone insert\\" on public.waitlist_signups\\n  for insert to anon, authenticated with check (true);\\ncreate policy \\"waitlist admin read\\" on public.waitlist_signups\\n  for select using (public.is_admin());\\n\\nrevoke all on public.waitlist_signups from anon, authenticated;\\ngrant insert (email, whatsapp, country, vehicle_id, source)\\n  on public.waitlist_signups to anon, authenticated;\\ngrant select on public.waitlist_signups to authenticated;\\n\\ncreate or replace function public.vehicle_vin(p_vehicle_id uuid)\\nreturns text\\nlanguage sql\\nstable\\nsecurity definer\\nset search_path = public\\nas $$\\n  select v.vin\\n  from public.vehicles v\\n  where v.id = p_vehicle_id\\n    and auth.uid() is not null\\n    and (\\n      public.is_admin()\\n      or v.seller_id = auth.uid()\\n      or exists (\\n        select 1 from public.purchase_requests pr\\n        where pr.vehicle_id = v.id\\n          and pr.buyer_id = auth.uid()\\n          and pr.mova_fee_payment_status = ''paid''\\n      )\\n    );\\n$$;\\n\\ndrop policy \\"reviews insert when eligible\\" on public.reviews;\\ncreate policy \\"reviews insert when eligible\\" on public.reviews\\n  for insert to authenticated\\n  with check (\\n    reviewer_id = auth.uid()\\n    and status = ''pending''\\n    and rating between 1 and 5\\n    and reviewer_id is distinct from reviewee_id\\n    and (\\n      (\\n        review_type = ''buyer_to_seller''\\n        and reviewee_shipper_id is null\\n        and shipment_request_id is null\\n        and exists (\\n          select 1\\n          from public.purchase_requests pr\\n          join public.vehicles v on v.id = pr.vehicle_id\\n          where pr.id = reviews.purchase_request_id\\n            and pr.buyer_id = auth.uid()\\n            and v.seller_id = reviews.reviewee_id\\n            and pr.mova_fee_payment_status = ''paid''\\n        )\\n      )\\n      or (\\n        review_type = ''seller_to_buyer''\\n        and reviewee_shipper_id is null\\n        and shipment_request_id is null\\n        and exists (\\n          select 1\\n          from public.purchase_requests pr\\n          join public.vehicles v on v.id = pr.vehicle_id\\n          where pr.id = reviews.purchase_request_id\\n            and v.seller_id = auth.uid()\\n            and pr.buyer_id = reviews.reviewee_id\\n            and pr.mova_fee_payment_status = ''paid''\\n        )\\n      )\\n      or (\\n        review_type = ''buyer_to_shipper''\\n        and reviewee_id is null\\n        and purchase_request_id is null\\n        and exists (\\n          select 1\\n          from public.shipment_requests sr\\n          where sr.id = reviews.shipment_request_id\\n            and sr.buyer_id = auth.uid()\\n            and sr.shipper_id = reviews.reviewee_shipper_id\\n            and sr.status = ''completed''\\n        )\\n      )\\n    )\\n  );"],"name":"prelaunch_and_waitlist","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260928224148","statements":["create or replace function public.purchase_requests_guard_negotiation()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n\\n  if exists (\\n    select 1 from public.vehicles v\\n    where v.id = old.vehicle_id and v.seller_id = auth.uid()\\n  ) then\\n    if old.negotiated_price_status <> ''accepted''\\n       and new.negotiated_price_status = ''proposed''\\n       and new.negotiated_price_usd is not null\\n       and new.negotiated_price_usd > 0\\n       and new.negotiated_price_usd < coalesce(\\n             old.vehicle_price_usd,\\n             (select price_usd from public.vehicles where id = old.vehicle_id)\\n           )\\n       and old.status in (''submitted'', ''under_review'', ''verified'')\\n    then\\n      new.negotiated_price_proposed_at := now();\\n      new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    else\\n      new.negotiated_price_usd := old.negotiated_price_usd;\\n      new.negotiated_price_status := old.negotiated_price_status;\\n      new.negotiated_price_proposed_at := old.negotiated_price_proposed_at;\\n      new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    end if;\\n\\n    new.vehicle_id := old.vehicle_id;\\n    new.buyer_id := old.buyer_id;\\n    new.shipping_rate_id := old.shipping_rate_id;\\n    new.status := old.status;\\n    new.vehicle_price_usd := old.vehicle_price_usd;\\n    new.mova_fee_usd := old.mova_fee_usd;\\n    new.mova_fee_payment_status := old.mova_fee_payment_status;\\n    new.mova_fee_stripe_session_id := old.mova_fee_stripe_session_id;\\n    new.mova_fee_checkout_url := old.mova_fee_checkout_url;\\n    new.fee_payment_requested_at := old.fee_payment_requested_at;\\n    new.payment_method := old.payment_method;\\n    new.payment_reference := old.payment_reference;\\n    new.bank_transfer_proof_path := old.bank_transfer_proof_path;\\n    new.bank_transfer_proof_uploaded_at := old.bank_transfer_proof_uploaded_at;\\n    new.bank_transfer_reviewed_by := old.bank_transfer_reviewed_by;\\n    new.bank_transfer_reviewed_at := old.bank_transfer_reviewed_at;\\n    new.bank_transfer_rejection_reason := old.bank_transfer_rejection_reason;\\n    new.notes := old.notes;\\n    new.assigned_admin_id := old.assigned_admin_id;\\n    new.created_at := old.created_at;\\n    return new;\\n  end if;\\n\\n  if old.buyer_id = auth.uid() then\\n    if old.negotiated_price_status = ''proposed''\\n       and new.negotiated_price_status = ''accepted''\\n    then\\n      new.negotiated_price_accepted_at := now();\\n      new.negotiated_price_usd := old.negotiated_price_usd;\\n      new.negotiated_price_proposed_at := old.negotiated_price_proposed_at;\\n    else\\n      new.negotiated_price_status := old.negotiated_price_status;\\n      new.negotiated_price_usd := old.negotiated_price_usd;\\n      new.negotiated_price_proposed_at := old.negotiated_price_proposed_at;\\n      new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    end if;\\n\\n    if old.mova_fee_payment_status in (''pending'', ''bank_transfer_rejected'')\\n       and new.mova_fee_payment_status = ''pending_manual_verification''\\n       and new.payment_method = ''bank_transfer''\\n       and new.bank_transfer_proof_path is not null\\n       and new.bank_transfer_proof_path is distinct from old.bank_transfer_proof_path\\n    then\\n      new.bank_transfer_proof_uploaded_at := now();\\n      new.bank_transfer_reviewed_by := null;\\n      new.bank_transfer_reviewed_at := null;\\n      new.bank_transfer_rejection_reason := null;\\n    else\\n      new.mova_fee_payment_status := old.mova_fee_payment_status;\\n      new.payment_method := old.payment_method;\\n      new.bank_transfer_proof_path := old.bank_transfer_proof_path;\\n      new.bank_transfer_proof_uploaded_at := old.bank_transfer_proof_uploaded_at;\\n      new.bank_transfer_reviewed_by := old.bank_transfer_reviewed_by;\\n      new.bank_transfer_reviewed_at := old.bank_transfer_reviewed_at;\\n      new.bank_transfer_rejection_reason := old.bank_transfer_rejection_reason;\\n    end if;\\n\\n    if old.mova_fee_checkout_url is null\\n       and new.shipping_rate_id is distinct from old.shipping_rate_id\\n       and (\\n         new.shipping_rate_id is null\\n         or exists (\\n           select 1\\n           from public.shipping_rates sr\\n           join public.vehicles v on v.id = old.vehicle_id\\n           where sr.id = new.shipping_rate_id\\n             and sr.active\\n             and sr.vehicle_size_type = v.vehicle_size_type\\n         )\\n       )\\n    then\\n      null;\\n    else\\n      new.shipping_rate_id := old.shipping_rate_id;\\n    end if;\\n\\n    new.vehicle_id := old.vehicle_id;\\n    new.buyer_id := old.buyer_id;\\n    new.status := old.status;\\n    new.vehicle_price_usd := old.vehicle_price_usd;\\n    new.mova_fee_usd := old.mova_fee_usd;\\n    new.mova_fee_stripe_session_id := old.mova_fee_stripe_session_id;\\n    new.mova_fee_checkout_url := old.mova_fee_checkout_url;\\n    new.fee_payment_requested_at := old.fee_payment_requested_at;\\n    new.payment_reference := old.payment_reference;\\n    new.notes := old.notes;\\n    new.assigned_admin_id := old.assigned_admin_id;\\n    new.created_at := old.created_at;\\n    return new;\\n  end if;\\n\\n  return old;\\nend;\\n$$;\\n\\nalter table public.purchase_requests\\n  drop column seller_details_revealed_at,\\n  drop column seller_name,\\n  drop column seller_email,\\n  drop column seller_phone,\\n  drop column seller_whatsapp;"],"name":"drop_direct_wire_contact_reveal","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
