insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260929201559","statements":["alter table public.vehicles\\n  add column vin_model_year_code text\\n    generated always as (upper(substr(vin, 10, 1))) stored;\\n\\ngrant select (vin_model_year_code) on public.vehicles to anon, authenticated;\\n\\ncreate unique index vehicles_vin_active_unique\\n  on public.vehicles (upper(vin))\\n  where status <> ''archived'';\\n\\ncreate or replace function public.vehicles_require_photo_to_approve()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if new.status = ''approved''\\n     and (tg_op = ''INSERT'' or old.status is distinct from ''approved'')\\n     and not exists (select 1 from public.vehicle_photos p where p.vehicle_id = new.id)\\n  then\\n    raise exception ''listing_has_no_photos''\\n      using errcode = ''check_violation'',\\n            hint = ''A listing needs at least one photo before it can be approved.'';\\n  end if;\\n  return new;\\nend;\\n$$;\\n\\nrevoke execute on function public.vehicles_require_photo_to_approve() from public, anon, authenticated;\\n\\ncreate trigger vehicles_require_photo_to_approve\\n  before insert or update on public.vehicles\\n  for each row execute procedure public.vehicles_require_photo_to_approve();"],"name":"import_year_duplicate_vin_photo_rule","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20260929201606","statements":["create or replace function public.seller_profiles_guard_admin_only_fields()\\nreturns trigger\\nlanguage plpgsql\\nsecurity definer\\nset search_path = public\\nas $$\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n\\n  if tg_op = ''INSERT'' then\\n    new.id_verified_at := null;\\n    new.full_name := null;\\n    if new.id_verification_status <> ''pending'' then\\n      new.id_verification_status := ''unverified'';\\n    end if;\\n    return new;\\n  end if;\\n\\n  new.id_verified_at := old.id_verified_at;\\n  new.full_name := old.full_name;\\n  if new.id_verification_status <> ''pending'' then\\n    new.id_verification_status := old.id_verification_status;\\n  end if;\\n  return new;\\nend;\\n$$;\\n\\nalter table public.seller_profiles drop column verification_status;"],"name":"drop_seller_profiles_verification_status","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
