insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20261004213140","statements":["select set_config(''request.jwt.claims'', ''{\\"role\\":\\"service_role\\"}'', true);\\ncreate sequence if not exists public.transaction_reference_seq;\\ncreate or replace function public.next_transaction_reference() returns text language sql security definer set search_path = '''' as $$\\n  select ''SM-'' || lpad(nextval(''public.transaction_reference_seq'')::text, 6, ''0'');\\n$$;\\nrevoke execute on function public.next_transaction_reference() from public, anon, authenticated;\\nalter table public.purchase_requests add column if not exists reference text;\\ndo $$ declare r record; begin\\n  for r in select id from public.purchase_requests where reference is null order by created_at, id loop\\n    update public.purchase_requests set reference = public.next_transaction_reference() where id = r.id;\\n  end loop; end $$;\\nalter table public.purchase_requests alter column reference set not null;\\ndo $$ begin\\n  if not exists (select 1 from pg_constraint where conname = ''purchase_requests_reference_key'') then\\n    alter table public.purchase_requests add constraint purchase_requests_reference_key unique (reference);\\n  end if; end $$;\\ncreate or replace function public.purchase_requests_reference() returns trigger language plpgsql security definer set search_path = '''' as $$\\nbegin\\n  if tg_op = ''INSERT'' then new.reference := public.next_transaction_reference(); else new.reference := old.reference; end if;\\n  return new;\\nend; $$;\\ndrop trigger if exists purchase_requests_reference on public.purchase_requests;\\ncreate trigger purchase_requests_reference before insert or update on public.purchase_requests for each row execute function public.purchase_requests_reference();\\nalter table public.purchase_requests\\n  add column if not exists escrow_reference text check (char_length(escrow_reference) <= 100),\\n  add column if not exists escrow_stage text check (escrow_stage in (''escrow_opened'',''escrow_funded'',''inspection_passed'',''handed_to_shipper'',''escrow_released''));\\ncreate or replace function public.purchase_requests_guard_negotiation() returns trigger language plpgsql security definer set search_path to ''public'' as $$\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then return new; end if;\\n  if exists (select 1 from public.vehicles v where v.id = old.vehicle_id and v.seller_id = auth.uid()) then\\n    if old.negotiated_price_status <> ''accepted'' and new.negotiated_price_status = ''proposed'' and new.negotiated_price_usd is not null and new.negotiated_price_usd > 0\\n       and new.negotiated_price_usd < coalesce(old.vehicle_price_usd, (select price_usd from public.vehicles where id = old.vehicle_id))\\n       and old.status in (''submitted'', ''under_review'', ''verified'') then\\n      new.negotiated_price_proposed_at := now(); new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    else\\n      new.negotiated_price_usd := old.negotiated_price_usd; new.negotiated_price_status := old.negotiated_price_status;\\n      new.negotiated_price_proposed_at := old.negotiated_price_proposed_at; new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    end if;\\n    new.vehicle_id := old.vehicle_id; new.buyer_id := old.buyer_id; new.shipping_rate_id := old.shipping_rate_id; new.status := old.status;\\n    new.vehicle_price_usd := old.vehicle_price_usd; new.mova_fee_usd := old.mova_fee_usd; new.mova_fee_payment_status := old.mova_fee_payment_status;\\n    new.mova_fee_stripe_session_id := old.mova_fee_stripe_session_id; new.mova_fee_checkout_url := old.mova_fee_checkout_url;\\n    new.mova_fee_payment_method_fingerprint := old.mova_fee_payment_method_fingerprint; new.fee_payment_requested_at := old.fee_payment_requested_at;\\n    new.payment_method := old.payment_method; new.payment_reference := old.payment_reference; new.bank_transfer_proof_path := old.bank_transfer_proof_path;\\n    new.bank_transfer_proof_uploaded_at := old.bank_transfer_proof_uploaded_at; new.bank_transfer_reviewed_by := old.bank_transfer_reviewed_by;\\n    new.bank_transfer_reviewed_at := old.bank_transfer_reviewed_at; new.bank_transfer_rejection_reason := old.bank_transfer_rejection_reason;\\n    new.escrow_reference := old.escrow_reference; new.escrow_stage := old.escrow_stage;\\n    new.notes := old.notes; new.assigned_admin_id := old.assigned_admin_id; new.created_at := old.created_at;\\n    return new;\\n  end if;\\n  if old.buyer_id = auth.uid() then\\n    if old.negotiated_price_status = ''proposed'' and new.negotiated_price_status = ''accepted'' then\\n      new.negotiated_price_accepted_at := now(); new.negotiated_price_usd := old.negotiated_price_usd; new.negotiated_price_proposed_at := old.negotiated_price_proposed_at;\\n    else\\n      new.negotiated_price_status := old.negotiated_price_status; new.negotiated_price_usd := old.negotiated_price_usd;\\n      new.negotiated_price_proposed_at := old.negotiated_price_proposed_at; new.negotiated_price_accepted_at := old.negotiated_price_accepted_at;\\n    end if;\\n    if old.mova_fee_payment_status in (''pending'', ''bank_transfer_rejected'') and new.mova_fee_payment_status = ''pending_manual_verification''\\n       and new.payment_method = ''bank_transfer'' and new.bank_transfer_proof_path is not null and new.bank_transfer_proof_path is distinct from old.bank_transfer_proof_path then\\n      new.bank_transfer_proof_uploaded_at := now(); new.bank_transfer_reviewed_by := null; new.bank_transfer_reviewed_at := null; new.bank_transfer_rejection_reason := null;\\n    else\\n      new.mova_fee_payment_status := old.mova_fee_payment_status; new.payment_method := old.payment_method; new.bank_transfer_proof_path := old.bank_transfer_proof_path;\\n      new.bank_transfer_proof_uploaded_at := old.bank_transfer_proof_uploaded_at; new.bank_transfer_reviewed_by := old.bank_transfer_reviewed_by;\\n      new.bank_transfer_reviewed_at := old.bank_transfer_reviewed_at; new.bank_transfer_rejection_reason := old.bank_transfer_rejection_reason;\\n    end if;\\n    if old.mova_fee_checkout_url is null and new.shipping_rate_id is distinct from old.shipping_rate_id\\n       and (new.shipping_rate_id is null or exists (select 1 from public.shipping_rates sr join public.vehicles v on v.id = old.vehicle_id\\n            where sr.id = new.shipping_rate_id and sr.active and sr.vehicle_size_type = v.vehicle_size_type)) then null;\\n    else new.shipping_rate_id := old.shipping_rate_id; end if;\\n    new.mova_fee_payment_method_fingerprint := old.mova_fee_payment_method_fingerprint;\\n    new.escrow_reference := old.escrow_reference; new.escrow_stage := old.escrow_stage;\\n    new.vehicle_id := old.vehicle_id; new.buyer_id := old.buyer_id; new.status := old.status; new.vehicle_price_usd := old.vehicle_price_usd;\\n    new.mova_fee_usd := old.mova_fee_usd; new.mova_fee_stripe_session_id := old.mova_fee_stripe_session_id; new.mova_fee_checkout_url := old.mova_fee_checkout_url;\\n    new.fee_payment_requested_at := old.fee_payment_requested_at; new.payment_reference := old.payment_reference; new.notes := old.notes;\\n    new.assigned_admin_id := old.assigned_admin_id; new.created_at := old.created_at;\\n    return new;\\n  end if;\\n  return old;\\nend; $$;\\nalter table public.transaction_status_history add column if not exists stage text, add column if not exists from_stage text;\\nalter table public.transaction_status_history drop column if exists status;\\nalter table public.transaction_status_history alter column stage set not null;\\nalter table public.transaction_status_history add constraint transaction_status_history_stage_format check (stage ~ ''^[a-z_]+\\\\.[a-z_]+$'');\\nalter table public.transaction_status_history drop constraint if exists transaction_status_history_purchase_request_id_fkey;\\nalter table public.transaction_status_history add constraint transaction_status_history_purchase_request_id_fkey foreign key (purchase_request_id) references public.purchase_requests(id) on delete restrict;\\nalter table public.transaction_status_history drop constraint if exists transaction_status_history_changed_by_fkey;\\nalter table public.transaction_status_history add column if not exists seq bigint generated always as identity;\\ncreate index if not exists transaction_status_history_pr_idx on public.transaction_status_history (purchase_request_id, seq);\\ndrop policy if exists \\"transaction history admin insert\\" on public.transaction_status_history;\\nrevoke insert, update, delete, truncate on public.transaction_status_history from anon, authenticated;\\ncreate or replace function public.transaction_history_append_only() returns trigger language plpgsql as $$\\nbegin raise exception ''transaction_status_history is append-only'' using errcode = ''insufficient_privilege''; end; $$;\\ndrop trigger if exists transaction_history_append_only on public.transaction_status_history;\\ncreate trigger transaction_history_append_only before update or delete on public.transaction_status_history for each row execute function public.transaction_history_append_only();\\ncreate or replace function public.record_transaction_stage(p_purchase_request_id uuid, p_stage text, p_from_stage text, p_note text default null) returns void language sql security definer set search_path = '''' as $$\\n  insert into public.transaction_status_history (purchase_request_id, stage, from_stage, changed_by, note) values (p_purchase_request_id, p_stage, p_from_stage, auth.uid(), p_note);\\n$$;\\nrevoke execute on function public.record_transaction_stage(uuid, text, text, text) from public, anon, authenticated;\\ncreate or replace function public.purchase_requests_record_history() returns trigger language plpgsql security definer set search_path = '''' as $$\\nbegin\\n  if tg_op = ''INSERT'' then perform public.record_transaction_stage(new.id, ''reservation.'' || new.status, null); return null; end if;\\n  if new.status is distinct from old.status then perform public.record_transaction_stage(new.id, ''reservation.'' || new.status, ''reservation.'' || old.status); end if;\\n  if new.mova_fee_payment_status is distinct from old.mova_fee_payment_status then perform public.record_transaction_stage(new.id, ''fee.'' || new.mova_fee_payment_status, ''fee.'' || old.mova_fee_payment_status); end if;\\n  if new.negotiated_price_status is distinct from old.negotiated_price_status then perform public.record_transaction_stage(new.id, ''price.'' || new.negotiated_price_status, ''price.'' || old.negotiated_price_status); end if;\\n  if new.escrow_stage is distinct from old.escrow_stage then\\n    perform public.record_transaction_stage(new.id, ''escrow.'' || coalesce(new.escrow_stage, ''cleared''), case when old.escrow_stage is null then null else ''escrow.'' || old.escrow_stage end);\\n  end if;\\n  if new.escrow_reference is distinct from old.escrow_reference then perform public.record_transaction_stage(new.id, ''escrow.reference_recorded'', null, new.escrow_reference); end if;\\n  return null;\\nend; $$;\\ndrop trigger if exists purchase_requests_record_history on public.purchase_requests;\\ncreate trigger purchase_requests_record_history after insert or update on public.purchase_requests for each row execute function public.purchase_requests_record_history();\\ncreate or replace function public.shipment_requests_record_history() returns trigger language plpgsql security definer set search_path = '''' as $$\\nbegin\\n  if tg_op = ''INSERT'' then perform public.record_transaction_stage(new.purchase_request_id, ''shipping.shipper_selected'', null, new.shipper_company_name); return null; end if;\\n  if new.shipping_status is distinct from old.shipping_status then perform public.record_transaction_stage(new.purchase_request_id, ''shipping.'' || new.shipping_status, ''shipping.'' || old.shipping_status); end if;\\n  if new.status is distinct from old.status then perform public.record_transaction_stage(new.purchase_request_id, ''shipment.'' || new.status, ''shipment.'' || old.status); end if;\\n  return null;\\nend; $$;\\ndrop trigger if exists shipment_requests_record_history on public.shipment_requests;\\ncreate trigger shipment_requests_record_history after insert or update on public.shipment_requests for each row execute function public.shipment_requests_record_history();\\ncreate or replace function public.disputes_record_history() returns trigger language plpgsql security definer set search_path = '''' as $$\\nbegin\\n  if tg_op = ''INSERT'' then perform public.record_transaction_stage(new.purchase_request_id, ''dispute.'' || new.status, null);\\n  elsif new.status is distinct from old.status then perform public.record_transaction_stage(new.purchase_request_id, ''dispute.'' || new.status, ''dispute.'' || old.status); end if;\\n  return null;\\nend; $$;\\ndrop trigger if exists disputes_record_history on public.disputes;\\ncreate trigger disputes_record_history after insert or update on public.disputes for each row execute function public.disputes_record_history();\\nrevoke execute on function public.purchase_requests_reference() from public, anon, authenticated;\\nrevoke execute on function public.purchase_requests_record_history() from public, anon, authenticated;\\nrevoke execute on function public.shipment_requests_record_history() from public, anon, authenticated;\\nrevoke execute on function public.disputes_record_history() from public, anon, authenticated;\\ninsert into public.transaction_status_history (purchase_request_id, stage, from_stage, changed_by, note)\\nselect pr.id, ''reservation.'' || pr.status, null, null, ''Current state when history began; earlier changes were not recorded.''\\nfrom public.purchase_requests pr where not exists (select 1 from public.transaction_status_history h where h.purchase_request_id = pr.id);"],"name":"transaction_reference_and_history","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20261005140601","statements":["create table if not exists public.admin_audit_log (\\n  id uuid primary key default gen_random_uuid(),\\n  seq bigint generated always as identity,\\n  admin_id uuid not null,\\n  action text not null check (action ~ ''^[a-z_]+\\\\.[a-z_]+$''),\\n  target_table text not null check (target_table ~ ''^[a-z_]+$''),\\n  target_id text,\\n  details jsonb not null default ''{}''::jsonb,\\n  created_at timestamptz not null default now()\\n);\\ncreate index if not exists admin_audit_log_target_idx on public.admin_audit_log (target_table, target_id, seq);\\ncreate index if not exists admin_audit_log_admin_idx on public.admin_audit_log (admin_id, seq);\\nalter table public.admin_audit_log enable row level security;\\ndrop policy if exists \\"admin audit log admin read\\" on public.admin_audit_log;\\ncreate policy \\"admin audit log admin read\\" on public.admin_audit_log for select using (public.is_admin());\\nrevoke insert, update, delete, truncate on public.admin_audit_log from anon, authenticated;\\ngrant select on public.admin_audit_log to authenticated;\\ncreate or replace function public.admin_audit_log_append_only() returns trigger language plpgsql as $$\\nbegin raise exception ''admin_audit_log is append-only'' using errcode = ''insufficient_privilege''; end; $$;\\ndrop trigger if exists admin_audit_log_append_only on public.admin_audit_log;\\ncreate trigger admin_audit_log_append_only before update or delete on public.admin_audit_log for each row execute function public.admin_audit_log_append_only();\\ncreate or replace function public.log_admin_action(p_action text, p_target_table text, p_target_id text, p_details jsonb default ''{}''::jsonb)\\nreturns uuid language plpgsql security definer set search_path = '''' as $$\\ndeclare v_id uuid;\\nbegin\\n  if not public.is_admin() then\\n    raise exception ''log_admin_action: admin session (with code) required'' using errcode = ''insufficient_privilege'';\\n  end if;\\n  insert into public.admin_audit_log (admin_id, action, target_table, target_id, details)\\n  values (auth.uid(), p_action, p_target_table, p_target_id, coalesce(p_details, ''{}''::jsonb))\\n  returning id into v_id;\\n  return v_id;\\nend; $$;\\nrevoke execute on function public.log_admin_action(text, text, text, jsonb) from public, anon;\\ngrant execute on function public.log_admin_action(text, text, text, jsonb) to authenticated;"],"name":"admin_audit_log","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20261005151254","statements":["alter table public.platform_settings\\n  add column if not exists require_buyer_id_check boolean not null default false;\\n\\ncreate or replace function public.is_buyer_id_check_required()\\nreturns boolean language sql stable security definer set search_path = '''' as $$\\n  select coalesce((select require_buyer_id_check from public.platform_settings where id), false);\\n$$;\\ngrant execute on function public.is_buyer_id_check_required() to anon, authenticated;\\n\\ncreate or replace function public.purchase_requests_require_buyer_id()\\nreturns trigger language plpgsql security definer set search_path = '''' as $$\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n  if public.is_buyer_id_check_required() and not exists (\\n    select 1 from public.buyer_profiles b\\n    where b.user_id = new.buyer_id and b.verification_status = ''verified''\\n  ) then\\n    raise exception ''buyer_id_check_required''\\n      using errcode = ''check_violation'',\\n            hint = ''Verify your ID (NIN) on your dashboard before reserving.'';\\n  end if;\\n  return new;\\nend;\\n$$;\\nrevoke execute on function public.purchase_requests_require_buyer_id() from public, anon, authenticated;\\n\\ndrop trigger if exists purchase_requests_require_buyer_id on public.purchase_requests;\\ncreate trigger purchase_requests_require_buyer_id\\n  before insert on public.purchase_requests\\n  for each row execute function public.purchase_requests_require_buyer_id();"],"name":"buyer_id_check_at_reservation","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
insert into supabase_migrations.schema_migrations select * from json_populate_record(null::supabase_migrations.schema_migrations, E'{"version":"20261005154113","statements":["alter table public.buyer_profiles\\n  add column if not exists id_country text check (id_country in (''NG'', ''GH'', ''TG'', ''BJ'')),\\n  add column if not exists id_method text check (id_method in (''ng_nin'', ''gh_card'', ''document'')),\\n  add column if not exists id_legal_name text check (char_length(id_legal_name) <= 200),\\n  add column if not exists id_record_name text check (char_length(id_record_name) <= 200),\\n  add column if not exists id_name_match text check (id_name_match in (''match'', ''close'', ''mismatch'')),\\n  add column if not exists id_document_type text check (id_document_type in (''national_id'', ''passport'')),\\n  add column if not exists id_document_path text,\\n  add column if not exists id_review_note text check (char_length(id_review_note) <= 1000),\\n  add column if not exists id_reviewed_by uuid,\\n  add column if not exists id_reviewed_at timestamptz,\\n  add column if not exists id_verified_at timestamptz;\\n\\ncreate or replace function public.buyer_profiles_guard_admin_only_fields()\\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\\nbegin\\n  if public.is_admin() or auth.role() = ''service_role'' then\\n    return new;\\n  end if;\\n  if tg_op = ''INSERT'' then\\n    new.nin_verification_status := ''unverified'';\\n    new.bvn_verification_status := ''unverified'';\\n    new.verification_status := ''unverified'';\\n    new.policy_accepted_at := case when new.policy_version is not null then now() else null end;\\n    new.id_country := null; new.id_method := null; new.id_legal_name := null; new.id_record_name := null;\\n    new.id_name_match := null; new.id_document_type := null; new.id_document_path := null; new.id_review_note := null;\\n    new.id_reviewed_by := null; new.id_reviewed_at := null; new.id_verified_at := null;\\n    return new;\\n  end if;\\n  new.nin_verification_status := old.nin_verification_status;\\n  new.bvn_verification_status := old.bvn_verification_status;\\n  new.verification_status := old.verification_status;\\n  new.id_country := old.id_country; new.id_method := old.id_method; new.id_legal_name := old.id_legal_name;\\n  new.id_record_name := old.id_record_name; new.id_name_match := old.id_name_match; new.id_document_type := old.id_document_type;\\n  new.id_document_path := old.id_document_path; new.id_review_note := old.id_review_note; new.id_reviewed_by := old.id_reviewed_by;\\n  new.id_reviewed_at := old.id_reviewed_at; new.id_verified_at := old.id_verified_at;\\n  if new.policy_version is not null and new.policy_version is distinct from old.policy_version then\\n    new.policy_accepted_at := now();\\n  else\\n    new.policy_version := old.policy_version;\\n    new.policy_accepted_at := old.policy_accepted_at;\\n  end if;\\n  return new;\\nend;\\n$$;\\n\\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\\nvalues (''buyer-id-documents'', ''buyer-id-documents'', false, 10485760, array[''image/jpeg'', ''image/png'', ''image/webp''])\\non conflict (id) do nothing;\\n\\ndrop policy if exists \\"buyer id documents owner insert\\" on storage.objects;\\ncreate policy \\"buyer id documents owner insert\\" on storage.objects\\n  for insert to authenticated\\n  with check (bucket_id = ''buyer-id-documents'' and (storage.foldername(name))[1] = (select auth.uid())::text);\\n\\ndrop policy if exists \\"buyer id documents owner delete\\" on storage.objects;\\ncreate policy \\"buyer id documents owner delete\\" on storage.objects\\n  for delete to authenticated\\n  using (bucket_id = ''buyer-id-documents'' and (storage.foldername(name))[1] = (select auth.uid())::text);\\n\\ncreate or replace function public.buyer_id_summary(p_buyer_id uuid)\\nreturns text language sql stable security definer set search_path = '''' as $$\\n  select case\\n    when b.verification_status <> ''verified'' then ''ID not verified yet''\\n    when b.id_method = ''ng_nin'' and b.id_name_match in (''match'', ''close'') then ''Nigerian NIN verified — name matches government record''\\n    when b.id_method = ''ng_nin'' then ''Nigerian NIN verified — name confirmed by ShipMova''\\n    when b.id_method = ''gh_card'' and b.id_name_match in (''match'', ''close'') then ''Ghana Card verified — name matches government record''\\n    when b.id_method = ''gh_card'' then ''Ghana Card verified — name confirmed by ShipMova''\\n    when b.id_method = ''document'' then\\n      (case b.id_country when ''TG'' then ''Togolese '' when ''BJ'' then ''Beninese '' else '''' end)\\n      || (case b.id_document_type when ''passport'' then ''passport'' else ''national ID'' end)\\n      || '' checked by ShipMova''\\n    else ''ID verified''\\n  end\\n  from public.buyer_profiles b\\n  where b.user_id = p_buyer_id\\n    and (\\n      p_buyer_id = auth.uid()\\n      or public.is_admin()\\n      or exists (select 1 from public.conversations c where c.buyer_id = p_buyer_id and c.seller_id = auth.uid())\\n      or exists (select 1 from public.purchase_requests pr join public.vehicles v on v.id = pr.vehicle_id\\n                 where pr.buyer_id = p_buyer_id and v.seller_id = auth.uid())\\n    );\\n$$;\\nrevoke execute on function public.buyer_id_summary(uuid) from public, anon;\\ngrant execute on function public.buyer_id_summary(uuid) to authenticated;"],"name":"buyer_id_at_signup","created_by":"tbakare2@gmail.com","idempotency_key":null,"rollback":null}');
